// Englische Oberfläche: der interne Code SE (Selbsterhaltung) wird dem Leser als SP (self-preservation) gezeigt.
// Betrifft nur sichtbaren Text, nie Daten oder Schlüssel.
const _SP_RE = /\bSE([1-9])/g;
const _SP_TEST = /\bSE[1-9]/;
function _spFix(node) {
  if (!node) return;
  if (node.nodeType === 3) { if (_SP_TEST.test(node.nodeValue)) node.nodeValue = node.nodeValue.replace(_SP_RE, "SP$1"); return; }
  if (node.nodeType !== 1) return;
  const w = document.createTreeWalker(node, NodeFilter.SHOW_TEXT, { acceptNode: n => {
    const p = n.parentNode && n.parentNode.nodeName;
    if (p === "SCRIPT" || p === "STYLE" || p === "TEXTAREA") return NodeFilter.FILTER_REJECT;
    return _SP_TEST.test(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
  } });
  const list = []; let n;
  while ((n = w.nextNode())) list.push(n);
  list.forEach(t => { t.nodeValue = t.nodeValue.replace(_SP_RE, "SP$1"); });
  node.querySelectorAll("[title],[alt],[aria-label],[placeholder]").forEach(el => ["title", "alt", "aria-label", "placeholder"].forEach(a => {
    const v = el.getAttribute(a);
    if (v && _SP_TEST.test(v)) el.setAttribute(a, v.replace(_SP_RE, "SP$1"));
  }));
}
try {
  new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(_spFix))).observe(document.body, { childList: true, subtree: true });
  _spFix(document.body);
} catch (e) { /* Anzeige-Korrektur ist optional */ }

// Version-Check: prüft beim Start ob eine neue Version vorliegt und erzwingt Reload
const APP_BUILD = "436";
(function checkForUpdate() {
  if (location.hostname === 'localhost' || location.hostname === '127.0.0.1') return;
  const BUILD_GUARD_KEY = 'kompass-build-reload-guard-' + APP_BUILD;
  if (sessionStorage.getItem(BUILD_GUARD_KEY)) return; // schon einmal neu geladen – kein Loop
  fetch("./version.json?t=" + Date.now(), { cache: "no-store" })
    .then(r => r.json())
    .then(data => {
      if (data && data.build && data.build !== APP_BUILD) {
        sessionStorage.setItem(BUILD_GUARD_KEY, '1'); // vor dem Reload setzen!
        if ("caches" in window) {
          caches.keys().then(keys => Promise.all(keys.map(k => caches.delete(k))))
            .then(() => { window.location.reload(true); });
        } else {
          window.location.reload(true);
        }
      }
    })
    .catch(() => {}); // kein Netz → still ignorieren
})();
const PROFILE_KEY = "enneagramm-kompass:profile";
