const REVIEWS_API = 'https://kompass-assistent.9rathmer.workers.dev/reviews';
// Schützt vor eingeschleustem HTML (Stored XSS) bei Texten, die Besucher einreichen.
function _escHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; });
}
// Der Admin-Code steht NICHT im Code: Er wird erst nach erfolgreicher Prüfung durch den Worker gesetzt.
let ADMIN_CODE = '';


function adminPage() {
  const app = document.getElementById('app');
  if (!ADMIN_CODE) {
    app.innerHTML = '<div style="max-width:400px;margin:4rem auto;padding:2rem;text-align:center;">' +
      '<p style="color:var(--ink);font-size:1rem;margin-bottom:1rem;">Admin-Code eingeben:</p>' +
      '<input id="admin-code-input" type="password" placeholder="Code..." ' +
      'style="width:100%;padding:0.6rem;font-size:1rem;border:1px solid var(--border);border-radius:8px;text-align:center;margin-bottom:0.8rem;">' +
      '<button onclick="_adminLogin()" ' +
      'style="background:var(--gold);border:none;border-radius:8px;padding:0.6rem 1.5rem;font-weight:700;cursor:pointer;">Einloggen</button>' +
      '</div>';
    return;
  }
  app.innerHTML = '<div style="max-width:680px;margin:2rem auto;padding:1rem;">' +
    '<h1 style="font-size:1.2rem;font-weight:700;color:var(--ink);margin-bottom:1.5rem;">Bewertungen verwalten</h1>' +
    '<div id="admin-liste"><p style="color:var(--muted);">Lade Bewertungen...</p></div>' +
    '</div>';
  _adminLoading();
}

function _adminLoading() {
  fetch(REVIEWS_API + '/wartend', { cache: 'no-store',
    headers: { 'X-Admin-Code': ADMIN_CODE } })
    .then(function(r){ return r.json(); })
    .then(function(data) {
      if (data.error) { ADMIN_CODE = ''; adminPage(); return; }
      const liste = data.reviews || [];
      const el = document.getElementById('admin-liste');
      if (!el) return;
      if (!liste.length) { el.innerHTML = '<p style="color:var(--muted);">Keine wartenden Bewertungen.</p>'; return; }
      el.innerHTML = liste.map(function(b, i) {
        const sternText = '★'.repeat(b.sterne) + '☆'.repeat(5-b.sterne);
        const datum = b.datum ? new Date(b.datum).toLocaleDateString('de-DE') : '';
        return '<div style="background:var(--ivory);border:1px solid var(--border);border-radius:10px;padding:1rem 1.2rem;margin-bottom:0.8rem;">' +
          '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:0.5rem;">' +
          '<div>' +
          '<span style="color:#f4a900;font-size:1.1rem;">' + sternText + '</span>' +
          '<span style="font-size:0.78rem;color:var(--muted);margin-left:0.5rem;">' + datum + '</span>' +
          '<p style="font-size:0.9rem;color:var(--ink);margin:0.5rem 0 0;line-height:1.6;">' + _escHtml(b.text || '(kein Kommentar)') + '</p>' +
          '</div></div>' +
          '<div style="display:flex;gap:0.5rem;margin-top:0.8rem;">' +
          '<button onclick="window._adminFreigeben(' + i + ')" ' +
          'style="background:#27ae60;color:#fff;border:none;border-radius:8px;padding:0.5rem 1rem;font-size:0.88rem;font-weight:700;cursor:pointer;">✓ Freigeben</button>' +
          '<button onclick="window._adminLoeschen(' + i + ')" ' +
          'style="background:#e74c3c;color:#fff;border:none;border-radius:8px;padding:0.5rem 1rem;font-size:0.88rem;font-weight:700;cursor:pointer;">✗ Delete</button>' +
          '</div></div>';
      }).join('');
    }).catch(function() {
      const el = document.getElementById('admin-liste');
      if (el) el.innerHTML = '<p style="color:red;">Error loading.</p>';
    });
}

function _adminCheck(route) {
  var v = (document.getElementById('admin-code-input').value || '').trim();
  if (!v) return;
  fetch(REVIEWS_API + '/wartend', { cache: 'no-store', headers: { 'X-Admin-Code': v } })
    .then(function(r) {
      if (r.status !== 200) throw new Error('abgelehnt');
      ADMIN_CODE = v;
      if (location.hash === '#' + route) { (route === 'admin' ? adminPage : adminWegweiserCodePage)(); }
      else { location.hash = route; }
    })
    .catch(function() { alert('Falscher Code'); });
}

window._adminLogin = function() { _adminCheck('admin'); };

window._adminFreigeben = function(index) {
  fetch(REVIEWS_API + '/freigeben', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Admin-Code': ADMIN_CODE },
    body: JSON.stringify({ index: index })
  })
    .then(function() { _adminLoading(); })
    .catch(function() { alert('Error beim Freigeben.'); });
};

window._adminLoeschen = function(index) {
  fetch(REVIEWS_API + '/loeschen', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Admin-Code': ADMIN_CODE },
    body: JSON.stringify({ index: index, from: 'wartend' })
  })
    .then(function() { _adminLoading(); })
    .catch(function() { alert('Error deleting.'); });
};


const COUNTRY_NAME_EN = {
  'DE':'Germany','AT':'Austria','CH':'Switzerland','US':'USA','GB':'United Kingdom',
  'FR':'France','NL':'Netherlands','IT':'Italy','ES':'Spain','SE':'Sweden',
  'NO':'Norway','DK':'Denmark','PL':'Poland','CZ':'Czech Republic','HU':'Hungary',
  'BE':'Belgium','LU':'Luxembourg','LI':'Liechtenstein','AU':'Australia','CA':'Canada',
  'JP':'Japan','CN':'China','IN':'India','BR':'Brazil','MX':'Mexico',
};

window._bewertungSenden = _bewertungSenden;
window._switchLangVoice = _switchLangVoice;
window.translateReview = function(btn) {
  try {
    var card = btn.parentElement;
    var textEl = card.querySelector('p');
    if (!textEl) return;
    if (btn.dataset.translated === '1') {
      textEl.textContent = textEl.dataset.orig;
      btn.textContent = '🌐 Translate';
      btn.dataset.translated = '0';
      return;
    }
    var orig = textEl.textContent;
    textEl.dataset.orig = orig;
    var preTranslated = textEl.dataset.textEn;
    if (preTranslated) {
      textEl.textContent = preTranslated;
      btn.textContent = '↩ Original';
      btn.dataset.translated = '1';
      return;
    }
    btn.textContent = '…';
    fetch('https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=en&dt=t&q=' + encodeURIComponent(orig))
      .then(function(r) { return r.json(); })
      .then(function(d) {
        var result = d[0].map(function(s) { return s[0]; }).join('');
        textEl.textContent = result;
        btn.textContent = '↩ Original';
        btn.dataset.translated = '1';
      })
      .catch(function() { btn.textContent = '🌐 Translate'; });
  } catch(e) { btn.textContent = '🌐 Translate'; }
};

function _bewertungSterneInit() {
  // Freigegebene Bewertungen laden
  fetch(REVIEWS_API + '/freigegeben', { cache: 'no-store' })
    .then(function(r){ return r.json(); })
    .then(function(data) {
      const liste = data.reviews || [];
      if (!liste.length) return;
      const section = document.getElementById('community-bewertungen');
      const container = document.getElementById('community-liste');
      if (!section || !container) return;
      container.innerHTML = liste.map(function(b) {
        const landDisplay = b.countryCode ? (COUNTRY_NAME_EN[b.countryCode] || b.land || '') : (b.land || '');
        const meta = [_escHtml(b.name), _escHtml(landDisplay) || null].filter(Boolean).join(' · ');
        const textEN = b.text_en || '';
        return '<div style="background:var(--ivory);border:1px solid var(--border);border-radius:10px;padding:1rem 1.2rem;" data-review-card>' +
          '<div style="display:flex;align-items:center;gap:0.5rem;margin-bottom:0.4rem;">' +
          '<span style="color:#f4a900;font-size:1rem;">' + '★'.repeat(b.sterne) + '☆'.repeat(5-b.sterne) + '</span>' +
          (meta ? '<span style="font-size:0.78rem;color:var(--muted);">' + meta + '</span>' : '') +
          '</div>' +
          '<p style="font-size:0.88rem;color:var(--ink);margin:0;line-height:1.6;" data-review-text data-text-en="' + _escHtml(textEN) + '">' + _escHtml(b.text || '') + '</p>' +
          '<button onclick="translateReview(this)" data-translated="0" style="margin-top:0.5rem;background:none;border:none;color:var(--gold-dark,#a07830);font-size:0.75rem;cursor:pointer;padding:0;">🌐 Translate</button>' +
          '</div>';
      }).join('');
      section.style.display = 'block';
    }).catch(function() {});
  const sterne = document.querySelectorAll('#bwrt-sterne span');
  if (!sterne.length) return;
  let gewaehlt = 0;
  sterne.forEach(function(s) {
    s.addEventListener('mouseover', function() {
      const n = parseInt(this.dataset.s);
      sterne.forEach(function(x, i) { x.style.opacity = i < n ? '1' : '0.3'; });
    });
    s.addEventListener('mouseout', function() {
      sterne.forEach(function(x, i) { x.style.opacity = i < gewaehlt ? '1' : '0.3'; });
    });
    s.addEventListener('click', function() {
      gewaehlt = parseInt(this.dataset.s);
      sterne.forEach(function(x, i) { x.style.opacity = i < gewaehlt ? '1' : '0.3'; });
      document.getElementById('bwrt-senden').dataset.sterne = gewaehlt;
    });
  });
}

function _bewertungSenden() {
  const btn = document.getElementById('bwrt-senden');
  const sterne = parseInt(btn.dataset.sterne || '0');
  const reviewText = document.getElementById('bwrt-text').value.trim();
  const nameVal = (document.getElementById('bwrt-name') || {value:''}).value.trim();
  if (!sterne) { alert('Please click stars first.'); return; }
  try { new Audio('sounds/purchase/bewertung_dank.mp3').play().catch(() => {}); } catch (e) {}
  const sternText = '★'.repeat(sterne) + '☆'.repeat(5 - sterne);
  const form = document.getElementById('bwrt-form');
  form.innerHTML = '<div style="text-align:center;padding:1.5rem 1rem;">' +
    '<div style="font-size:2.5rem;margin-bottom:0.6rem;">' + sternText + '</div>' +
    '<p style="font-size:1.05rem;font-weight:700;color:var(--ink);margin:0 0 0.4rem;">Thank you for your review!</p>' +
    '<p style="font-size:0.88rem;color:var(--muted);margin:0;">It will be reviewed and published soon.</p>' +
    '</div>';
  // Auto-detect country via free IP geolocation
  fetch('https://ipapi.co/json/')
    .then(function(r){ return r.json(); })
    .catch(function(){ return {}; })
    .then(function(geo) {
      const review = {
        sterne: sterne,
        text: reviewText,
        name: nameVal || null,
        land: geo.country_name || null,
        countryCode: geo.country_code || null
      };
      return fetch(REVIEWS_API + '/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(review)
      });
    })
    .catch(function() {});
}

function _formatEnglishDate(iso) {
  const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  const [y, m, d] = iso.split("-").map(Number);
  return MONTHS[m - 1] + " " + parseInt(d, 10) + ", " + y;
}

function _gsLatestUpdateBadgeHTML() {
  if (typeof CHANGELOG === "undefined" || !CHANGELOG.length) return "";
  const latest = CHANGELOG.reduce((a, b) => a.date > b.date ? a : b);
  return `<button class="related-link-btn" data-route="updates" style="display:inline-flex;align-items:center;gap:0.4rem;background:var(--ivory);border:1.5px solid var(--gold,#c4a456);border-radius:20px;padding:0.4rem 1rem;font-family:-apple-system,sans-serif;font-size:0.78rem;font-weight:700;color:var(--copper,#a5603d);letter-spacing:0.02em;cursor:pointer;">
    <span style="width:7px;height:7px;border-radius:50%;background:var(--gold,#c4a456);display:inline-block;"></span>
    Last update: ${_formatEnglishDate(latest.date)}
  </button>`;
}

function updatesPage() {
  const unlocked = hasHeilwissen();
  const entries = (typeof CHANGELOG !== "undefined" ? CHANGELOG : []);
  const rows = entries.map(e => {
    const dateStr = _formatEnglishDate(e.date);
    if (unlocked) {
      return `<li style="display:flex;gap:1rem;align-items:baseline;padding:0.9rem 0;border-bottom:1px solid var(--border);">
        <span style="flex-shrink:0;width:7.5rem;font-size:0.78rem;color:var(--muted);font-family:-apple-system,sans-serif;">${dateStr}</span>
        ${e.route
          ? `<a href="#" onclick="event.preventDefault();go('${e.route}')" style="color:var(--ink);text-decoration:underline;text-decoration-color:var(--copper);text-underline-offset:2px;font-size:0.92rem;">${e.text_en || e.text}</a>`
          : `<span style="font-size:0.92rem;color:var(--ink);">${e.text_en || e.text}</span>`}
      </li>`;
    }
    const teaser = e.route && e.route.startsWith("beruehmte-") ? "New celebrity portrait available"
      : e.route && e.route.startsWith("kriminalpsychologie-") ? "New criminal case analysed"
      : "New content available";
    return `<li style="display:flex;gap:1rem;align-items:baseline;padding:0.9rem 0;border-bottom:1px solid var(--border);">
      <span style="flex-shrink:0;width:7.5rem;font-size:0.78rem;color:var(--muted);font-family:-apple-system,sans-serif;">${dateStr}</span>
      <span style="font-size:0.92rem;color:var(--ink);">${teaser}</span>
    </li>`;
  }).join("");

  return shell(`
    <div class="page-container">
      ${pageHeader("updates")}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">The Compass keeps growing</p>
          <h1 class="typentest-titel" style="margin-bottom:0.6rem;">All Updates</h1>
          <p class="typentest-intro">See how regularly new content, portraits and features are added.</p>
          <ul style="list-style:none;margin:1.2rem 0 0;padding:0;hyphens:manual;-webkit-hyphens:manual;">${rows}</ul>
        </div>
      </div>
    </div>
  `);
}

function neuigkeitenSection() {
  if (typeof CHANGELOG === 'undefined' || !CHANGELOG.length) return '';
  const SEEN_KEY = 'kompass:changelog-seen';
  const lastSeen = localStorage.getItem(SEEN_KEY) || '';
  const neu = CHANGELOG.filter(e => e.date > lastSeen);
  if (!neu.length) return '';
  const latest = CHANGELOG.reduce((a, b) => a.date > b.date ? a : b).date;
  const unlocked = hasHeilwissen();
  const items = neu.map(e => {
    if (unlocked) {
      return `<li style="display:flex;align-items:baseline;gap:0.5rem;margin-bottom:0.35rem;">
      <span style="color:var(--copper,#b87830);flex-shrink:0;">✦</span>
      ${e.route
        ? `<a href="#" onclick="event.preventDefault();go('${e.route}')" style="color:var(--ink,#2c2824);text-decoration:underline;text-decoration-color:var(--copper,#b87830);text-underline-offset:2px;">${e.text_en || e.text}</a>`
        : `<span>${e.text_en || e.text}</span>`}
    </li>`;
    }
    const teaser = e.route && e.route.startsWith('beruehmte-') ? 'New celebrity portrait available'
      : e.route && e.route.startsWith('kriminalpsychologie-') ? 'New criminal case analysed'
      : 'New content available';
    return `<li style="display:flex;align-items:baseline;gap:0.5rem;margin-bottom:0.35rem;">
      <span style="color:var(--copper,#b87830);flex-shrink:0;">✦</span>
      <span>${teaser}</span>
    </li>`;
  }).join('');
  return `
    <section id="neuigkeiten-banner" style="max-width:520px;margin:0 auto 1.4rem;padding:0 1rem;">
      <div style="position:relative;border-left:3px solid var(--copper,#b87830);border-radius:0 8px 8px 0;background:var(--paper-deep,#ede8dc);padding:0.9rem 1.1rem;">
        <button onclick="(function(){localStorage.setItem('kompass:changelog-seen','${latest}');document.getElementById('neuigkeiten-banner').remove();})()" style="position:absolute;top:0.5rem;right:0.6rem;background:none;border:none;font-size:1rem;color:var(--muted,#888);cursor:pointer;line-height:1;padding:0.1rem 0.3rem;" aria-label="Close">×</button>
        <details>
          <summary style="cursor:pointer;font-size:0.7rem;font-weight:700;letter-spacing:0.15em;text-transform:uppercase;color:var(--copper,#b87830);margin:0;padding-right:1.4rem;list-style:none;">New since your last visit (${neu.length})</summary>
          <ul style="list-style:none;margin:0.6rem 0 0;padding:0;font-size:0.88rem;color:var(--ink,#2c2824);line-height:1.5;hyphens:manual;-webkit-hyphens:manual;">${items}</ul>
        </details>
      </div>
    </section>`;
}

