export function animalResearcherMatchBlock(currentRoute) {
  const others = ANIMAL_RESEARCHER_MATCHES.filter(m => m.route !== currentRoute);
  if (!others.length) return "";
  const items = others.map(m =>
    `<button class="related-link-btn" data-route="${m.route}" style="background:none;border:1px solid var(--gold);color:var(--copper);border-radius:20px;padding:.35rem .95rem;font-size:0.82rem;font-family:'EB Garamond',serif;cursor:pointer;white-space:nowrap;">${m.name} (${m.subtyp}) – ${m.tier} &#8594;</button>`
  ).join("");
  return `
    <details style="margin-top:1.5rem;padding-top:1rem;border-top:1px solid var(--border);">
      <summary style="cursor:pointer;font-size:0.75rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);">&#10022;&nbsp;Animal-Researcher Match: More Examples</summary>
      <div style="display:flex;flex-wrap:wrap;gap:.5rem;margin-top:.75rem;">${items}</div>
    </details>
  `;
}

export function relatedLinks(links) {
  if (!links || !links.length) return "";
  const ALBUM_KEYS = ["jazz", "musik", "stille", "songs", "lieder", "alben", "homoeopathie-songs"];
  const isAlbum = r => ALBUM_KEYS.some(k => r.includes(k));
  const hasAlbum = links.some(l => isAlbum(l.route));
  const hasOverview = links.some(l => !isAlbum(l.route));
  const heading = hasAlbum && hasOverview ? "Related Portraits and Albums"
                : hasAlbum                ? "Related Albums"
                :                          "Related Portraits";
  const buttons = links.map(({route, label}) =>
    `<button class="related-link-btn" data-route="${route}" style="background:none;border:1px solid var(--gold);color:var(--copper);border-radius:20px;padding:.35rem .95rem;font-size:0.82rem;font-family:'EB Garamond',serif;cursor:pointer;white-space:nowrap;">${label} &#8594;</button>`
  ).join("");
  return `
    <div style="margin-top:2rem;padding-top:1.25rem;border-top:1px solid var(--border);">
      <p style="font-size:0.75rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:0 0 .6rem;">&#10022;&nbsp;${heading}</p>
      <div style="display:flex;flex-wrap:wrap;gap:.5rem;">${buttons}</div>
    </div>
  `;
}

function healingPage() {
  const code = getProfile();
  // Replace #healing in browser history with #subtype/code so back-button works correctly
  history.replaceState(null, "", "#subtype/" + code);
  state.route = "subtype/" + code;
  window._currentRoute = state.route;
  return subtypePage(code);
}

function oelForType(code) {
  const num = parseInt(String(code).replace(/\D/g, ""), 10);
  return aetherischeOele.find((o) => o.typ === num) || null;
}

const OIL_WOUND_EN = {
  1:"I am flawed and imperfect.", 2:"I am worthless without being useful.", 3:"I am only valuable through achievement.",
  4:"I am different, I do not belong.", 5:"The world drains me.", 6:"There is no secure footing.",
  7:"The pain will destroy me.", 8:"Weakness means destruction.", 9:"I do not matter."
};
const OIL_TYPE_NAMES_EN = {
  1:"The Perfectionist", 2:"The Helper", 3:"The Performer",
  4:"The Individualist", 5:"The Observer", 6:"The Loyalist",
  7:"The Enthusiast", 8:"The Protector", 9:"The Peacemaker"
};
function oilCard(oel) {
  const en = OILS_EN[oel.typ] || {};
  const name    = en.name      || oel.name;
  const wirkung = en.wirkung   || oel.wirkung;
  const vertiefung = en.vertiefung || oel.vertiefung;
  const image   = en.image     || oel.image;
  const typLabelEN = `Type ${oel.typ} · ${OIL_TYPE_NAMES_EN[oel.typ] || ""}`;
  return `
    <article class="oil-card" id="oil-type-${oel.typ}">
      <div class="oil-card__image">
        <img src="${image}" alt="Type ${oel.typ} · ${name}" loading="lazy" />
      </div>
      <div class="oil-card__body">
        <span class="oil-card__type">${typLabelEN}</span>
        <h3>${name}</h3>
        <p class="oil-card__wound"><strong>Core Wound:</strong> “${OIL_WOUND_EN[oel.typ] || oel.urWunde}”</p>
        <p class="oil-card__effect">${wirkung}</p>
        ${vertiefung ? `<p class="oil-card__text">${vertiefung}</p>` : ""}
        ${AFFILIATE_LINKS.oel[name] ? affiliateBoxHtml("oel", name) : ""}
      </div>
    </article>
  `;
}

function oilsPage() {
  return shell(`
    ${pageHeader("oils")}
    <section class="knowledge-hero">
      <div>
        <p class="eyebrow">Essential Oils · Wound Level</p>
        <h1>Essential Oils for the Core Wound</h1>
        <p class="lead-small">Every Enneagram type is assigned an essential oil that acts directly at the wound level – where the deepest imprint resides. Scents reach the limbic system immediately and can bring healing movement into entrenched patterns.</p>
      </div>
      <aside>
        <span>One assignment</span>
        <strong>9 Types · 9 Oils</strong>
        <p>These oils are intentionally placed alongside the Remedies Compass (Page 4) – as their own, equally important section of the wound level.</p>
      </aside>
    </section>
    <section class="knowledge-grid">
      <article class="knowledge-card knowledge-card--expanded">
        <h2>The Nine Oils of the Wound Level</h2>
        <div class="oil-grid">
          ${aetherischeOele.map(oilCard).join("")}
        </div>
        <p class="remedy-note">Apply mindfully and diluted (e.g. as a room scent, in a carrier oil or via inhalation). Not a substitute for medical or therapeutic support.</p>
        <p class="remedy-note" style="margin-top:.6rem;">Looking for the practical application: <a href="javascript:void(0)" data-route="praxistipps-heilpraktiker/atemritual-aetherische-oele" style="color:var(--copper);text-decoration:underline;">The Breathing Ritual with Essential Oils</a> – a concrete exercise for using each of these nine scents deliberately for self-regulation.</p>
        ${bookTip("die-enneagramm-aromatherapie", "9 types, 9 core wounds, 9 soul scents &ndash; essential oils as an entry point to the depths of character.", "Die Enneagramm-Aromatherapie")}
      </article>
    </section>
  `);
}

function tcmForType(code) {
  const num = parseInt(String(code).replace(/\D/g, ""), 10);
  return tcmData.find((t) => t.typ === num) || null;
}

const TCM_TYPE_NAMES_EN = {
  1: "The Perfectionist", 2: "The Helper", 3: "The Performer",
  4: "The Individualist", 5: "The Observer", 6: "The Loyalist",
  7: "The Enthusiast", 8: "The Challenger", 9: "The Peacemaker"
};
function tcmCard(tcm) {
  const c = text.routes.tcm;
  const en = TCM_EN[tcm.typ] || {};
  const typLabelEN = `Type ${tcm.typ} · ${TCM_TYPE_NAMES_EN[tcm.typ] || ""}`;
  const meridian   = en.meridian    || tcm.meridian;
  const element    = en.element     || tcm.element;
  const organzeit  = en.organzeit   || tcm.organzeit;
  const polaritaet = en.polaritaet  || tcm.polaritaet;
  const leitorgan  = en.leitorgan   || tcm.leitorgan;
  const symptom    = en.symptom     || tcm.symptom;
  const ausgleich  = en.ausgleich   || tcm.ausgleich;
  const empfehlung = en.empfehlung  || tcm.empfehlung;
  const tagesplan  = en.tagesplan   || tcm.tagesplan;
  return `
    <article class="tcm-card" style="--tcm-element-color:${tcm.elementFarbe}">
      <div class="tcm-card__header">
        <span class="tcm-card__type">${typLabelEN}</span>
        <button class="tcm-card__element-badge" data-tcm-element="${element}" title="More on the ${element} element">${element} ↗</button>
      </div>
      <h3 class="tcm-card__meridian">${meridian}</h3>
      <div class="tcm-card__meta">
        <span class="tcm-card__organzeit">⏱ ${organzeit}</span>
        <span class="tcm-card__polaritaet">${polaritaet} · ${leitorgan}</span>
      </div>
      <p class="tcm-card__symptom">${symptom}</p>
      <p class="tcm-card__ausgleich"><strong>${c.ausgleichLabel}:</strong> ${ausgleich}</p>
      <div class="tcm-card__details">
        <h4>${c.empfehlungLabel}</h4>
        <ul>${empfehlung.map((e) => `<li>${e}</li>`).join("")}</ul>
        <h4>${c.tagesplanLabel}</h4>
        <ol class="tcm-tagesplan">
          ${tagesplan.map((s) => `<li><span class="tcm-tagesplan__time">${s.uhrzeit}</span><span class="tcm-tagesplan__label">${s.label}</span><span class="tcm-tagesplan__text">${s.text}</span></li>`).join("")}
        </ol>
      </div>
    </article>
  `;
}


