const TEXTUMFANG_STAND = { datum: "Oct 24, 2026", woerterMio: "2.1", normseiten: "7,980", buecher: "27" };
// PRAXISTIPPS_ANZAHL is maintained manually (the TIPPS array is local to praxistippsHeilpraktikerPage) –
