function werkSection() {
  const w = text.werk;
  const filterLabels = {
    all:                     "All",
    enneagramm:              "Enneagram",
    homoeopathie:            "Homeopathy",
    "persoenliche-entwicklung": "Personal Development",
    kalender:                "Calendar",
  };
  const filterBar = Object.entries(filterLabels).map(([key, label]) =>
    `<button class="werk-filter${key === "all" ? " is-active" : ""}" data-werk-filter="${key}">${label}</button>`
  ).join("");

  const cards = werkRegister.map((book) => {
    const isPending = book.status === "link_pruefen";
    const linkLabel = book.category === "kalender" ? "To the Calendar" : book.id.includes("hoerbuch") ? "To the Audiobook" : w.openBook;
    const verlagsLink = isPending
      ? `<span class="deepen-link deepen-link--pending">${w.linkPending}</span>`
      : `<a class="deepen-link" href="${book.link}" target="_blank" rel="noopener">${linkLabel} →</a>`;
    const bodLink = !isPending && book.bodUrl
      ? `<a class="deepen-link deepen-link--bod" href="${book.bodUrl}" target="_blank" rel="noopener">Buy at BoD →</a>`
      : "";
    const coverImg = `<img src="${CDN}assets/covers/${book.id}.jpg" alt="" loading="lazy"
      onerror="if(!this.dataset.fallback){this.dataset.fallback='1';this.src='${R2_CDN}assets/covers/${book.id}.jpg';}else{this.parentElement.style.display='none';}"
      style="width:60px;flex-shrink:0;border-radius:4px;object-fit:cover;align-self:flex-start;box-shadow:0 1px 4px rgba(0,0,0,.18);">`;
    return `
      <article class="werk-card" data-category="${book.category || ""}" style="display:flex;gap:.75rem;align-items:flex-start;">
        <div style="width:60px;flex-shrink:0;">${coverImg}</div>
        <div style="min-width:0;">
          <h3 style="margin-top:0;">${book.title}</h3>
          <p class="werk-card__themes">${w.themes}: ${book.themes.join(" · ")}</p>
          <div class="werk-card__links">${verlagsLink}${bodLink}</div>
        </div>
      </article>`;
  }).join("");

  return `
    <section class="werk">
      <div class="section-divider"><span>${w.title}</span></div>
      <p class="lead-small werk__lead">${w.lead}</p>
      <div class="werk-filterbar">${filterBar}</div>
      <div class="werk-grid">${cards}</div>
    </section>
  `;
}

// ── QUIZ ENGINE ──────────────────────────────────────────────────────────

function _quizSeededRng(seed) {
  let s = (seed >>> 0) || 1;
  return function() {
    s ^= s << 13; s ^= s >>> 17; s ^= s << 5;
    return (s >>> 0) / 0xffffffff;
  };
}

function _quizShuffleAnswers(question, rng) {
  const items = question.a.map((text, i) => ({ text, correct: i === question.c }));
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

function _quizPickQuestions(seed) {
  const qd = window._quizData || [];
  const rng = _quizSeededRng(seed);
  const pick = (pool, n) => {
    const arr = pool.slice().sort(() => rng() - 0.5);
    return arr.slice(0, Math.min(n, arr.length));
  };
  const leicht = qd.filter(q => q.d === "leicht");
  const mittel = qd.filter(q => q.d === "mittel");
  const schwer = qd.filter(q => q.d === "schwer");
  const chosen = [...pick(leicht, 4), ...pick(mittel, 4), ...pick(schwer, 2)];
  return chosen.sort(() => rng() - 0.5);
}

window._startQuiz = function() {
  try {
    const seed = Date.now() & 0xffffffff;
    const rng  = _quizSeededRng(seed);
    const questions = _quizPickQuestions(seed);
    if (!questions || !questions.length) {
      alert("Quiz-Daten nicht geladen. Bitte Seite neu laden.");
      return;
    }
    _quizState = {
      phase: "question",
      questions,
      current: 0,
      score: 0,
      answered: false,
      selectedIdx: null,
      shuffledAnswers: _quizShuffleAnswers(questions[0], rng),
      seed,
    };
    if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
  } catch(e) {
    alert("Quiz-Error: " + e.message);
  }
};

window._answerQuiz = function(idx) {
  if (!_quizState || _quizState.answered) return;
  _quizState.answered = true;
  _quizState.selectedIdx = idx;
  if (_quizState.shuffledAnswers[idx].correct) _quizState.score++;
  if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
};

window._nextQuizQuestion = function() {
  if (!_quizState) return;
  _quizState.current++;
  if (_quizState.current >= _quizState.questions.length) {
    _quizState.phase = "result";
  } else {
    _quizState.answered = false;
    _quizState.selectedIdx = null;
    const rng = _quizSeededRng((Date.now() ^ (_quizState.current * 2654435761)) >>> 0);
    _quizState.shuffledAnswers = _quizShuffleAnswers(_quizState.questions[_quizState.current], rng);
  }
  if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
};

window._resetQuiz = function() {
  _quizState = null;
  if (location.hash === "#quiz") { render(); } else { location.hash = "quiz"; }
};


// ── Globale Search ────────────────────────────────────────────────────────────────────────────

// ── Suche: Normalisierung, Mehrwort-Suche, Synonyme, Tippfehler-Toleranz ──────────────
const _SUCHE_SYNONYME_RAW = {"psychogram": ["psychogramm", "personlichkeitsprofil"], "portrait": ["portrat", "porträt"], "chart": ["diagram", "schaubild", "graph"], "test": ["quiz", "questionnaire"], "wing": ["fluegel", "flügel"], "animal": ["tier", "archetype"]};
const _SUCHE_SYNONYME = (() => {
  const m = {};
  Object.keys(_SUCHE_SYNONYME_RAW).forEach(k => {
    const all = [k, ..._SUCHE_SYNONYME_RAW[k]].map(s => _sNorm(s));
    all.forEach(a => { m[a] = all.filter(b => b !== a); });
  });
  return m;
})();

function _sNorm(s) {
  return String(s == null ? "" : s).toLowerCase()
    .replace(/ß/g, "ss")
    .normalize("NFD").replace(/[̀-ͯ]/g, "")
    .replace(/ae/g, "a").replace(/oe/g, "o").replace(/ue/g, "u")
    .replace(/[^a-z0-9]+/g, " ").trim();
}

function _sLev(a, b, max) {
  if (Math.abs(a.length - b.length) > max) return max + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    let rowMin = i;
    for (let j = 1; j <= b.length; j++) {
      const v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      cur.push(v);
      if (v < rowMin) rowMin = v;
    }
    if (rowMin > max) return max + 1;
    prev = cur;
  }
  return prev[b.length];
}

const _sCache = new WeakMap();
function _sPrep(obj, label, extra) {
  let c = _sCache.get(obj);
  if (!c) {
    const l = _sNorm(label);
    c = { l, h: _sNorm(label + " " + (extra || "")), w: l.split(" ").filter(Boolean) };
    _sCache.set(obj, c);
  }
  return c;
}

// tokens: [{ alts: ["psychogramm", "personlichkeitsprofil"], len }]
function _sTokens(q) {
  return _sNorm(q).split(" ").filter(Boolean).map(t => ({ t, alts: [t, ...(_SUCHE_SYNONYME[t] || [])] }));
}

// Liefert eine Punktzahl (>0) oder 0, wenn nicht passend. fuzzy = Tippfehler-Toleranz an.
function _sScore(c, tokens, fuzzy) {
  let total = 0;
  for (const tk of tokens) {
    let best = 0;
    for (const a of tk.alts) {
      if (c.l.startsWith(a)) best = Math.max(best, 100);
      else if (c.w.some(w => w.startsWith(a))) best = Math.max(best, 80);
      else if (c.l.includes(a)) best = Math.max(best, 60);
      else if (c.h.includes(a)) best = Math.max(best, 30);
    }
    if (!best && fuzzy) {
      const max = tk.t.length <= 3 ? 0 : tk.t.length <= 5 ? 1 : 2;
      if (max) {
        for (const w of c.w) {
          if (_sLev(w, tk.t, max) <= max || _sLev(w.slice(0, tk.t.length), tk.t, max) <= max) { best = 15; break; }
        }
      }
    }
    if (!best) return 0;
    total += best;
  }
  return total / tokens.length;
}

function _sucheResults(q) {
  if (!LAENDER_REGIONEN && !_sucheWaitLaender) {
    _sucheWaitLaender = true;
    _prefetchData("laender", () => {
      _sucheWaitLaender = false;
      const upd = window._updateSuche || window._updateSearch;
      if (window._currentRoute === "suche" && _sucheQuery && upd) upd(_sucheQuery);
    });
  }
  const tokens = _sTokens(q);
  const empty = () => ({ subtypen: [], portraits: [], register: [], zitate: [], laender: [], fuzzy: false });
  if (!tokens.length) return empty();

  const run = (fuzzy) => {
    const res = empty();
    const add = (list, obj, label, extra, item) => {
      const s = _sScore(_sPrep(obj, label, extra), tokens, fuzzy);
      if (s > 0) { item._s = s; list.push(item); }
    };

    Object.values(subtypeProfiles).forEach(p => {
      add(res.subtypen, p, p.code + " " + (p.title_en || p.title), [p.titleAlt, p.archetype, p.subtitle || ""].join(" "),
        { label: enCode(p.code) + " \u2013 " + (p.title_en || p.title), sub: p.archetype_en || p.archetype || "", route: "subtype/" + p.id });
    });

    KRIMINAL_PORTRAITS.forEach(p => {
      add(res.portraits, p, p.name, (p.beschreibung || "") + " " + (p.typ || ""), { label: p.name, sub: p.typ || "", route: p.route });
    });

    registerEntriesEN.forEach(e => {
      add(res.register, e, e.term, e.description || "", { label: e.term, sub: (e.description || "").slice(0, 80), route: e.route });
    });

    (LAENDER_REGIONEN || []).forEach(r => {
      r.laender.forEach(l => {
        add(res.laender, l, l.name, "", { label: l.name, sub: r.region + " · Type " + l.typ, route: "laenderzuordnungen|ll-" + l.iso });
      });
    });

    (window._zitateData || []).forEach(z => {
      const label = '"' + z.q.slice(0, 65) + (z.q.length > 65 ? "…" : "") + '"';
      add(res.zitate, z, z.q, z.a + " " + (z.t || ""), { label, sub: z.a + (z.y ? " (" + z.y + ")" : ""), route: "zitate" });
    });

    ["subtypen", "portraits", "register", "zitate", "laender"].forEach(k => res[k].sort((a, b) => b._s - a._s));
    res.fuzzy = fuzzy;
    return res;
  };

  const exact = run(false);
  const total = exact.subtypen.length + exact.portraits.length + exact.register.length + exact.zitate.length + exact.laender.length;
  if (total > 0) return exact;
  return run(true);
}

function _sucheResultsHtml(res, q) {
  const total = res.subtypen.length + res.portraits.length + res.register.length + res.zitate.length + res.laender.length;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
  if (total === 0) return `<p class="suche-hint">No results found for &ldquo;${esc(q)}&rdquo;.</p><div class="suche-ask"><p>Sounds like a question? The Guide answers questions about everything in the app.</p><button type="button" class="suche-ask-btn" data-ask="${esc(q)}">Ask the Guide</button></div>`;

  const words = String(q).trim().split(/\s+/).filter(w => w.length > 1).map(w => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const hlRe = words.length ? new RegExp("(" + words.join("|") + ")", "ig") : null;
  const hl = (txt) => hlRe ? esc(txt).replace(hlRe, '<mark class="suche-hl">$1</mark>') : esc(txt);

  const group = (title, items) => {
    if (!items.length) return "";
    const rest = items.length - 6;
    const more = rest > 0
      ? `<button type="button" class="suche-more-btn" data-more="1" data-n="${items.length}">Show all ${items.length}</button>`
      : "";
    return `<div class="suche-group">
      <h3 class="suche-group-title">${title} <span class="suche-count">${items.length}</span></h3>
      ${items.map((it, i) => `<button class="suche-result${i >= 6 ? " suche-result--extra" : ""}" data-route="${it.route}">
        <span class="suche-result-label">${hl(it.label)}</span>
        ${it.sub ? `<span class="suche-result-sub">${it.sub}</span>` : ""}
      </button>`).join("")}${more}</div>`;
  };

  const askBlock = _sucheIsQuestion(q) ? `<div class="suche-ask"><p>Sounds like a question? The Guide answers questions about everything in the app.</p><button type="button" class="suche-ask-btn" data-ask="${esc(q)}">Ask the Guide</button></div>` : "";
  const hint = res.fuzzy ? `<p class="suche-hint">No exact matches \u2013 showing similar results (typos are tolerated).</p>` : "";
  return `<p class="suche-total">${total} ${total === 1 ? "result" : "results"}</p>${hint}${askBlock}
    ${group("Subtypes", res.subtypen)}
    ${group("Criminal Portraits", res.portraits)}
    ${group("Register &amp; Charts", res.register)}
    ${group("Countries", res.laender)}
    ${group("Quotes of the Wise", res.zitate)}`;
}

function _sucheBindResults(box) {
  box.querySelectorAll("[data-route]").forEach(btn => {
    btn.addEventListener("click", () => { _sucheQuery = ""; go(btn.dataset.route); });
  });
}
if (!window._sucheMoreBound) {
  window._sucheMoreBound = true;
  document.addEventListener("click", e => {
    const b = e.target.closest && e.target.closest(".suche-more-btn");
    if (b) { b.closest(".suche-group").classList.add("is-open"); b.remove(); }
  });
}

window._updateSearch = function(q) {
  _sucheQuery = q;
  const box = document.getElementById("suche-ergebnisse");
  if (!box) return;
  clearTimeout(_sucheMissTimer);
  if (q.length < 2) {
    box.innerHTML = `<p class="suche-hint">Enter at least 2 characters\u2026</p>`;
    _sucheRenderSuggestions({ register: [], portraits: [], subtypen: [] }, q);
    return;
  }
  const res = _sucheResults(q);
  box.innerHTML = _sucheResultsHtml(res, q);
  _sucheBindResults(box);
  _sucheRenderSuggestions(res, q);
  const total = res.subtypen.length + res.portraits.length + res.register.length + res.zitate.length + res.laender.length;
  if (total === 0) _sucheMissTimer = setTimeout(() => { if (_sucheQuery === q) _sucheLogMiss(q); }, 1400);
};

// ── Vorschläge beim Tippen, Wegweiser-Hinweis, anonyme Zählung erfolgloser Suchen ──
function _sucheSuggestions(res) {
  const seen = new Set();
  const pool = [...res.register, ...res.portraits, ...res.subtypen]
    .filter(it => res.fuzzy || it._s >= 60)
    .sort((a, b) => b._s - a._s || a.label.length - b.label.length);
  const out = [];
  for (const it of pool) {
    if (seen.has(it.label)) continue;
    seen.add(it.label);
    out.push(it);
    if (out.length >= 6) break;
  }
  return out;
}

function _sucheRenderSuggestions(res, q) {
  const box = document.getElementById("suche-vorschlaege");
  if (!box) return;
  const items = q.length >= 2 ? _sucheSuggestions(res) : [];
  if (!items.length) { box.innerHTML = ""; box.classList.remove("is-open"); return; }
  const esc = s => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
  box.innerHTML = items.map(it => `<button type="button" class="suche-sugg" role="option" data-route="${it.route}">${esc(it.label)}</button>`).join("");
  box.classList.add("is-open");
  box.querySelectorAll("[data-route]").forEach(btn => {
    btn.addEventListener("click", () => { _sucheQuery = ""; go(btn.dataset.route); });
  });
}

window._sucheKey = function(e) {
  const box = document.getElementById("suche-vorschlaege");
  if (!box) return;
  const items = [...box.querySelectorAll(".suche-sugg")];
  if (!items.length) return;
  const cur = items.findIndex(b => b.classList.contains("is-active"));
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    const next = e.key === "ArrowDown" ? (cur + 1) % items.length : (cur <= 0 ? items.length - 1 : cur - 1);
    items.forEach((b, i) => b.classList.toggle("is-active", i === next));
  } else if (e.key === "Enter" && cur >= 0) {
    e.preventDefault();
    items[cur].click();
  } else if (e.key === "Escape") {
    box.innerHTML = ""; box.classList.remove("is-open");
  }
};

window._sucheAskWegweiser = function(q) {
  const panel = document.getElementById("wegweiser-panel");
  const btn = document.getElementById("wegweiser-btn");
  if (!panel || !btn) return;
  if (getComputedStyle(panel).display === "none") btn.click();
  const inp = document.getElementById("wegweiser-input");
  if (inp) { inp.value = q; inp.focus(); }
};

if (!window._sucheAskBound) {
  window._sucheAskBound = true;
  document.addEventListener("click", e => {
    const b = e.target.closest && e.target.closest(".suche-ask-btn");
    if (b) window._sucheAskWegweiser(b.dataset.ask || "");
  });
}

let _sucheMissTimer = 0;
const _sucheMissSent = new Set();
function _sucheLogMiss(q) {
  const t = String(q).trim().toLowerCase();
  if (t.length < 3 || t.length > 40 || _sucheMissSent.has(t)) return;
  _sucheMissSent.add(t);
  try {
    fetch("https://kompass-assistent.9rathmer.workers.dev/search-miss", {
      method: "POST", headers: { "Content-Type": "text/plain" }, keepalive: true,
      body: JSON.stringify({ q: t, lang: "en" })
    }).catch(() => {});
  } catch (e) {}
}

function _sucheIsQuestion(q) {
  const s = String(q).trim();
  return s.indexOf("?") !== -1 || s.split(/\s+/).length >= 4;
}


function suchePage() {
  const hasQ = _sucheQuery.length >= 2;
  return shell(`
    ${pageHeader("suche")}
    <section class="narrow suche-page" style="padding:1.5rem 1rem 4rem;">
      <div class="suche-box">
        <svg class="suche-box-icon" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input class="suche-input" id="suche-input" type="search"
               placeholder="Subtypes, Portraits, Charts, Quotes…"
               oninput="window._updateSearch(this.value)"
               onkeydown="window._sucheKey(event)"
               value="${_sucheQuery.replace(/"/g, '&quot;')}"
               autocomplete="off" spellcheck="false" />
      </div>
      <div id="suche-vorschlaege" class="suche-vorschlaege" role="listbox"></div>
      <div id="suche-ergebnisse">
        ${hasQ ? _sucheResultsHtml(_sucheResults(_sucheQuery), _sucheQuery) : `<p class="suche-hint">Enter at least 2 characters…</p>`}
      </div>
    </section>
  `);
}



