function _bqaPortraitsForCode(code) {
  const all = []
    .concat(typeof BERUEHMT_PORTRAITS !== "undefined" ? BERUEHMT_PORTRAITS : [])
    .concat(typeof KRANKHEITS_PORTRAITS !== "undefined" ? KRANKHEITS_PORTRAITS : [])
    .concat(typeof KRIMINAL_PORTRAITS !== "undefined" ? KRIMINAL_PORTRAITS : []);
  const seenRoutes = new Set();
  const byName = new Map();
  const order = [];
  for (const p of all) {
    if (!p.subtyp || !p.subtyp.startsWith(code)) continue;
    if (seenRoutes.has(p.route)) continue;
    seenRoutes.add(p.route);
    if (!byName.has(p.name)) { byName.set(p.name, []); order.push(p.name); }
    const imgVal = BQA_IMG_MAP[p.route] || (p.route.indexOf("beruehmte-") === 0 ? p.route : null);
    const imgSrc = !imgVal ? null : (imgVal.startsWith(".") || imgVal.startsWith("http")) ? imgVal : ("https://pub-2851309644cc48aea2a2ae780b41b196.r2.dev/assets/portraits/" + imgVal + "-portrait.jpg");
    const fbName = !imgVal || imgVal.startsWith(".") || imgVal.startsWith("http") ? null : imgVal;
    byName.get(p.name).push({ route: p.route, subtyp: p.subtyp, img: imgSrc, fb: fbName ? ("/assets/portraits/" + fbName + "-portrait.jpg") : null });
  }
  return order.map(name => {
    const entries = byName.get(name);
    return { name, subtyp: entries[0].subtyp, route: entries[0].route,
      img: entries[0].img, fb: entries[0].fb, extraRoutes: entries.slice(1) };
  });
}
window._bqaToggleWing = function(btn, wing) {
  const bar = btn.closest(".bqa-wing-bar");
  bar.querySelectorAll(".bqa-wing-btn").forEach(function(b){ b.classList.remove("active"); b.style.background = "var(--paper)"; b.style.color = "var(--ink)"; });
  btn.classList.add("active");
  btn.style.background = btn.getAttribute("data-color") || "var(--copper)";
  btn.style.color = "#fff";
  const grid = bar.nextElementSibling;
  if (!grid || !grid.classList.contains("bqa-people-grid")) return;
  let shown = 0;
  grid.querySelectorAll("[data-bqa-wing]").forEach(function(tile){
    const match = !wing || tile.getAttribute("data-bqa-wing") === wing;
    tile.style.display = match ? "" : "none";
    if (match) shown++;
  });
  const countEl = bar.previousElementSibling && bar.previousElementSibling.querySelector(".bqa-wing-count");
  if (countEl) countEl.textContent = shown + " shown";
  bar.scrollIntoView({ block: "nearest" });
};
