function diagnosetestPage() {
  const ds = diagnoseState;

  // ── Phase: Intro ────────────────────────────────────────────────────────────
  if (ds.phase === "intro") {
    return shell(`
      ${pageHeader("diagnosetest")}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Enneagram Diagnostic Test</p>
          <h1 class="typentest-titel">Which Type Am I?</h1>
          <p class="typentest-intro">This test guides you through nine personality profiles. For each section, check the statements that apply to you. At the end, the evaluation will show which Enneagram type you are closest to.</p>
          <div class="typentest-hinweis" style="margin-bottom:1.2rem;">
            <strong>Important note before you start:</strong> No test can truly prove your type – because you fill it out yourself, and we are often blind to our own psychological and inner aspects. The result is always only an <em>approximation</em>: an invitation to familiarize yourself with the questions of the Enneagram. Approach the sections with openness – without expecting to find the final answer right away.
          </div>
          <ul class="typentest-hinweis" style="list-style:none;padding:0;margin:1.2rem 0;">
            <li style="padding:0.35rem 0;border-bottom:1px solid var(--line);">&#8226; 9 sections with approx. 28&ndash;30 statements each</li>
            <li style="padding:0.35rem 0;border-bottom:1px solid var(--line);">&#8226; Check everything that applies to you</li>
            <li style="padding:0.35rem 0;border-bottom:1px solid var(--line);">&#8226; The order is random &ndash; no type is named in advance</li>
            <li style="padding:0.35rem 0;">&#8226; Duration: approx. 10&ndash;15 minutes</li>
          </ul>
          ${bookTip("wer-du-wirklich-bist-band-1", "The nine types in their depth – protective patterns, passions, and the path to essence.", "Wer du wirklich bist – Band 1")}
          <button class="typentest-start-btn" data-diag-start>Start Test &#8594;</button>
        </div>
      </div>
    `);
  }

  // ── Phase: Step ─────────────────────────────────────────────────────────────
  if (ds.phase === "step") {
    const s = ds.step;
    const entry = DIAGNOSETEST[ds.order[s]];
    const typ = entry.typ;
    const checked = ds.checks[typ] || [];
    const pct = Math.round(((s + 1) / 9) * 100);
    const isLast = s === 8;

    const items = entry.aussagen.map((text, i) => {
      const isChecked = checked.includes(i);
      return `<label class="diag-item${isChecked ? " diag-item--checked" : ""}">
        <input type="checkbox" data-diag-check data-diag-idx="${i}"${isChecked ? " checked" : ""}>
        <span>${text}</span>
      </label>`;
    }).join("");

    return shell(`
      ${pageHeader("diagnosetest")}
      <div class="typentest-wrap">
        <div class="typentest-card">
          <p class="eyebrow">Section ${s + 1} of 9</p>
          <div style="width:100%;height:6px;background:rgba(114,102,90,0.15);border-radius:3px;margin:0.4rem 0 1.2rem;">
            <div style="width:${pct}%;height:6px;border-radius:3px;background:var(--copper,#a5603d);transition:width 0.3s;"></div>
          </div>
          <h2 class="typentest-titel" style="font-size:1.3rem;margin-bottom:0.3rem;">Which statements apply to you?</h2>
          <p class="typentest-intro" style="margin-bottom:0.8rem;">Check all statements that you find accurate.</p>
          <div class="diag-list">${items}</div>
          <div class="diag-nav">
            ${s > 0 ? `<button class="typentest-start-btn" style="background:transparent;color:var(--copper,#a5603d);border:1.5px solid var(--copper,#a5603d);" data-diag-back>&#8592; Back</button>` : `<span></span>`}
            <button class="typentest-start-btn" data-diag-next>${isLast ? "Show Result &#8594;" : "Next &#8594;"}</button>
          </div>
        </div>
      </div>
    `);
  }

  // ── Phase: Result ───────────────────────────────────────────────────────────
  if (ds.phase === "result") {
    playMilestone("test-abgeschlossen");
    const scores = DIAGNOSETEST.map(entry => ({
      typ: entry.typ,
      name: entry.name,
      total: entry.aussagen.length,
      score: (ds.checks[entry.typ] || []).length,
    }));
    const sorted = [...scores].sort((a, b) => b.score - a.score);
    const winner = sorted[0];
    const maxScore = winner.score || 1;

    const bars = sorted.map((s, i) => `
      <li class="${i === 0 ? "is-top" : ""}">
        <span class="diag-scores__label">Type ${s.typ} &ndash; ${s.name.replace("The ", "")}</span>
        <span class="diag-scores__bar-wrap"><span class="diag-scores__bar" style="width:${Math.round((s.score / maxScore) * 100)}%"></span></span>
        <span class="diag-scores__pts">${s.score}</span>
      </li>`).join("");

    return shell(`
      ${pageHeader("diagnosetest")}
      <div class="typentest-wrap">
        <div class="typentest-card typentest-card--result">
          <div class="diag-result__heading">
            <p class="eyebrow">Your Result</p>
            <div class="diag-result__typ">Type ${winner.typ} &ndash; ${winner.name}</div>
            <p class="typentest-intro">Out of ${winner.total} statements, you checked <strong>${winner.score}</strong> as accurate.</p>
            ${TYPKURZ[winner.typ] ? `<p style="font-size:0.95rem;line-height:1.6;color:var(--ink);margin:0.8rem 0 0;font-style:italic;">${TYPKURZ[winner.typ]}</p>` : ""}
          </div>
          <ul class="diag-scores">${bars}</ul>
          <div style="margin:1.5rem 0;background:linear-gradient(135deg,#f5e8cc,#eedda0);border:2px solid var(--gold);border-radius:12px;padding:1.4rem 1.2rem;text-align:left;">
            <p style="font-size:0.75rem;letter-spacing:.1em;text-transform:uppercase;color:var(--copper);margin:0 0 .3rem;">Would you like to go deeper?</p>
            <p style="font-family:'EB Garamond',serif;font-size:1.1rem;color:var(--ink);margin:0 0 .5rem;line-height:1.3;">With full access, you will see the complete profile of your type &mdash; remedies, charts, and all 27 subtypes.</p>
            <button class="cta-gold-btn" data-route="freischalt" style="background:var(--gold-dark);color:var(--copper);border:3px solid #8a5a1a;border-radius:10px;padding:.7rem 1.8rem;font-size:0.95rem;font-weight:700;cursor:pointer;font-family:'EB Garamond',serif;box-shadow:0 4px 14px rgba(0,0,0,.2);">Unlock now &#8594;</button>
          </div>
          <div class="typentest-cta-group" style="margin-top:1.5rem;display:flex;flex-direction:column;gap:0.7rem;">
            <p class="typentest-berater-label">Request a consultation appointment:</p>
            <a class="typentest-cta-btn" href="mailto:detlefrathmer@t-online.de?subject=Request%20a%20Typing%20Consultation">✉ Request consultation with Detlef Rathmer</a>
            <a class="typentest-cta-btn typentest-cta-btn--wa" href="https://wa.me/4915758786201?text=I%20would%20like%20to%20request%20a%20typing%20consultation." target="_blank" rel="noopener">WhatsApp Detlef Rathmer</a>
            <a class="typentest-cta-btn" href="mailto:rathmer.david.business@gmail.com?subject=Request%20a%20Typing%20Consultation">✉ Request consultation with David L. Rathmer</a>
            <a class="typentest-cta-btn typentest-cta-btn--wa" href="https://wa.me/4915901902479?text=I%20would%20like%20to%20request%20a%20typing%20consultation." target="_blank" rel="noopener">WhatsApp David L. Rathmer</a>
            <button class="typentest-start-btn" style="background:transparent;color:var(--copper,#a5603d);border:1.5px solid var(--copper,#a5603d);" data-diag-reset>Retake Test</button>
            <button class="typentest-start-btn" data-route="start">Go to Homepage</button>
          </div>
        </div>
      </div>
    `);
  }

  return shell(`${pageHeader("diagnosetest")}<div class="typentest-wrap"><p>Error in test.</p></div>`);
}

function bindDiagnosetest() {
  document.querySelector("[data-diag-start]")?.addEventListener("click", () => {
    const order = [0,1,2,3,4,5,6,7,8].sort(() => Math.random() - 0.5);
    diagnoseState = { phase: "step", step: 0, order, checks: {} };
    history.pushState({test:true}, "");
    render();
  });

  document.querySelector("[data-diag-next]")?.addEventListener("click", () => {
    if (diagnoseState.step < 8) {
      diagnoseState.step++;
    } else {
      diagnoseState.phase = "result";
    }
    history.pushState({test:true}, "");
    render();
  });

  document.querySelector("[data-diag-back]")?.addEventListener("click", () => {
    if (diagnoseState.step > 0) { diagnoseState.step--; render(); }
  });

  document.querySelectorAll("[data-diag-check]").forEach(cb => {
    cb.addEventListener("change", () => {
      const typ = DIAGNOSETEST[diagnoseState.order[diagnoseState.step]].typ;
      if (!diagnoseState.checks[typ]) diagnoseState.checks[typ] = [];
      const idx = parseInt(cb.dataset.diagIdx);
      const arr = diagnoseState.checks[typ];
      if (cb.checked) {
        if (!arr.includes(idx)) arr.push(idx);
      } else {
        const i = arr.indexOf(idx);
        if (i > -1) arr.splice(i, 1);
      }
      cb.closest(".diag-item")?.classList.toggle("diag-item--checked", cb.checked);
    });
  });

  document.querySelector("[data-diag-reset]")?.addEventListener("click", () => {
    diagnoseState = { phase: "intro", step: 0, order: [], checks: {} };
    render();
  });
}

