function subtypeChartsPage() {
  const code = state.route.split("/")[1] || null;

  // Detailansicht: alle Seiten eines Subtypes
  if (code) {
    const entry = subtypeEntry(code);
    if (!entry || !entry.visualPages || !entry.visualPages.length) {
      return shell(`
        <section class="narrow" style="padding:1.5rem 1rem 0;">
          <button class="ghost-link" data-route="subtypen-schaubilder">← Back to Overview</button>
        </section>
        <section class="narrow centered" style="padding:1rem;">
          <p>No charts have been added for this subtype yet.</p>
        </section>
      `);
    }
    const tc = typeColorFromCode(code);
    const pagesHtml = entry.visualPages.map(pg => `
      <figure class="vollseite-karte" style="margin:0 0 1.5rem;">
        <p class="vollseite-karte__hint">Tap to enlarge</p>
        <div class="card-pg-wrap">
          <img src="${pg.src}" alt="${pg.alt}" class="vollseite-karte__img" loading="lazy"
            onerror="this.closest('.vollseite-karte').style.display='none'" />
          <div class="card-pg-compass" aria-hidden="true">${compassMark("mini")}</div>
        </div>
        <figcaption class="vollseite-karte__titel">${pg.title}${pg.caption ? ` · <span style="font-weight:400;opacity:.7;">${pg.caption}</span>` : ""}</figcaption>
      </figure>
    `).join("");

    return shell(`
      ${pageHeader("subtypen-schaubilder")}
      <section class="narrow" style="padding:1rem 1rem 0;">
        <button class="ghost-link" data-route="subtypen-schaubilder">← All Subtypes</button>
      </section>
      <section class="narrow centered" style="padding:.75rem 1rem 1rem;">
        <p class="eyebrow" style="color:${tc}">${entry.code}</p>
        <h1 style="color:${tc};font-size:1.8rem;">${entry.title_en || entry.title}</h1>
        <p class="lead-small">${entry.coreSentence_en || entry.coreSentence || ""}</p>
      </section>
      <section class="narrow" style="padding:0 1rem 2rem;">
        ${pagesHtml}
        <button class="secondary" style="width:100%;margin-top:.5rem;" data-route="subtypen-schaubilder">← Back to Overview</button>
      </section>
    `);
  }

  // Übersicht: alle 27 Subtypes als klickbare Kacheln, gruppiert nach Typ
  const typeNames = {
    1:"Type 1 · The Improver", 2:"Type 2 · The Helper", 3:"Type 3 · The Achiever",
    4:"Type 4 · The Individualist", 5:"Type 5 · The Investigator", 6:"Type 6 · The Loyalist",
    7:"Type 7 · The Enthusiast", 8:"Type 8 · The Challenger", 9:"Type 9 · The Peacemaker"
  };
  const instLabels = { se: "Self-Preservation", so: "Social", sx: "Sexual" };

  const groupsHtml = [1,2,3,4,5,6,7,8,9].map(n => {
    const tc = typeColor(n);
    const codes = ["se","so","sx"].map(inst => `${inst}${n}`);
    const tilesHtml = codes.map(c => {
      const e = subtypeEntry(c);
      const inst = c.slice(0,2);
      const thumb = e?.visualPages?.[0]?.src || "";
      return `
        <button class="subtyp-schaubilder-tile" data-route="subtypen-schaubilder/${c}" style="border-color:${tc};">
          ${thumb ? `<img src="${thumb}" alt="${c} Vorschau" loading="lazy" style="width:100%;border-radius:6px 6px 0 0;display:block;" onerror="this.style.display='none'" />` : ""}
          <div style="padding:.6rem .75rem .75rem;">
            <span style="font-size:.7rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:${tc};">${instLabels[inst]}</span>
            <p style="margin:.15rem 0 0;font-size:.88rem;font-weight:600;hyphens:auto;overflow-wrap:break-word;">${e?.title_en || e?.title || c.toUpperCase()}</p>
            <p style="margin:.15rem 0 0;font-size:.75rem;color:#888;">${e?.visualPages?.length || 0} Charts</p>
          </div>
        </button>
      `;
    }).join("");
    return `
      <div style="margin-bottom:1.5rem;">
        <h2 style="font-size:1rem;font-weight:700;color:${tc};border-left:3px solid ${tc};padding-left:.6rem;margin:0 0 .75rem;">${typeNames[n]}</h2>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:.75rem;">
          ${tilesHtml}
        </div>
      </div>
    `;
  }).join("");

  return shell(`
    ${pageHeader("subtypen-schaubilder")}
    <section class="narrow centered" style="padding:1rem 1rem .5rem;">
      <p class="eyebrow">Charts · All 27 Subtypes</p>
      <h1>Subtype Charts</h1>
      <p class="lead-small">All original charts for the 27 Enneagram subtypes — tap a subtype to see all charts.</p>
    </section>
    <section class="narrow" style="padding:.5rem 1rem 2rem;">
      ${groupsHtml}
      ${relatedLinks([
        {route:"subtypen-checklisten", label:"Subtype Checklists"},
        {route:"bedeutung-27-subtypen", label:"Meaning of the 27 Subtypes"},
        {route:"horney-triaden", label:"Horney Triads"},
      ])}
    </section>
  `);
}

// Distinct, muted category color palette (deliberately separate from TYPE_COLORS so it's
// never confused with the Enneagram type colors) – loosely inspired by medical-textbook
// conventions (cardiovascular reddish, musculoskeletal earthy, respiratory airy blue-grey,
// skin skin-toned, nervous system blue, immune system wine-red, oncology muted dark), but
// desaturated enough to sit well with the Compass's calm overall palette.
const PSYCHOSOMATIK_KATEGORIEN = [
  { key: "herz-kreislauf", label: "Cardiovascular System", farbe: "#b6483f" },
  { key: "bewegungsapparat", label: "Musculoskeletal System", farbe: "#8a7860" },
  { key: "atemwege", label: "Respiratory System & Lungs", farbe: "#4a7f91" },
  { key: "verdauung", label: "Digestive System", farbe: "#ab7d42" },
  { key: "niere", label: "Kidney & Bladder", farbe: "#3d6b5c" },
  { key: "haut", label: "Skin", farbe: "#c99b7a" },
  { key: "augen", label: "Eyes", farbe: "#4d7a8c" },
  { key: "hormone-stoffwechsel", label: "Hormones & Metabolism", farbe: "#7d6a8c" },
  { key: "nerven-psyche", label: "Nervous System & Psyche", farbe: "#46688f" },
  { key: "immunsystem", label: "Immune System & Autoimmune", farbe: "#7a3d4a" },
  { key: "onkologie", label: "Oncology", farbe: "#5c4a5e" },
  { key: "psychiatrie", label: "Psychiatric Conditions", farbe: "#6a4d6e" },
  { key: "sonstige", label: "Other Conditions", farbe: "#6b6558" },
];

let PSYCHOSOMATIK_KRANKHEITEN = null;
_LAZY_DATA.psychosomatik = { spec: "./data/lazy/psychosomatik.js", assign: m => { PSYCHOSOMATIK_KRANKHEITEN = m.PSYCHOSOMATIK_KRANKHEITEN; } };

// Roadmap of the roughly 100 most common conditions in Western industrialized nations
// (Germany/Europe), categorized like PSYCHOSOMATIK_KATEGORIEN. Written up one at a time
// and then moved into PSYCHOSOMATIK_KRANKHEITEN. Until then they appear on the overview
// page as "in preparation" without their own detail page.
const PSYCHOSOMATIK_GEPLANT = {
  "herz-kreislauf": [],
  "bewegungsapparat": [],
  "atemwege": [],
  "verdauung": [],
  "haut": [],
  "hormone-stoffwechsel": [],
  "nerven-psyche": [],
  "immunsystem": [],
  "onkologie": [],
  "sonstige": [],
};

function _psychosomatikBuecherHtml() {
  const w = text.werk;
  const cardsFor = (cat) => werkRegister.filter(b => b.category === cat).map((book) => {
    const isPending = book.status === "link_pruefen";
    const verlagsLink = isPending
      ? `<span class="deepen-link deepen-link--pending">${w.linkPending}</span>`
      : `<a class="deepen-link" href="${book.link}" target="_blank" rel="noopener">${w.openBook} →</a>`;
    const bodLink = !isPending && book.bodUrl
      ? `<a class="deepen-link deepen-link--bod" href="${book.bodUrl}" target="_blank" rel="noopener">Buy at BoD →</a>`
      : "";
    const coverImg = `<img src="${CDN}assets/covers/${book.id}.jpg" alt="" loading="lazy"
      onerror="if(!this.dataset.fallback){this.dataset.fallback='1';this.src='${R2_CDN}assets/covers/${book.id}.jpg';}else{this.parentElement.style.display='none';}"
      style="width:60px;flex-shrink:0;border-radius:4px;object-fit:cover;align-self:flex-start;box-shadow:0 1px 4px rgba(0,0,0,.18);">`;
    return `
      <article class="werk-card" style="display:flex;gap:.75rem;align-items:flex-start;">
        <div style="width:60px;flex-shrink:0;">${coverImg}</div>
        <div style="min-width:0;">
          <h3 style="margin-top:0;">${book.title}</h3>
          <p class="werk-card__themes">${w.themes}: ${book.themes.join(" · ")}</p>
          <div class="werk-card__links">${verlagsLink}${bodLink}</div>
        </div>
      </article>`;
  }).join("");

  return `
    <section class="werk" style="margin-top:2.5rem;">
      <div class="section-divider"><span>Specialist Books on Healing</span></div>
      <p class="lead-small werk__lead">The publishing program on homeopathy and Enneagram healing arts &ndash; the professional foundation this Psychosomatics Register also draws on.</p>
      <div class="werk-grid">${cardsFor("homoeopathie")}</div>
    </section>
    <section class="werk" style="margin-top:2rem;">
      <div class="section-divider"><span>Spiritual &amp; Personal Healing Books</span></div>
      <p class="lead-small werk__lead">Beyond the specialist literature, the publishing program also offers spiritual and personal-development titles on healing and passion.</p>
      <div class="werk-grid">${cardsFor("persönliche-entwicklung")}</div>
    </section>
  `;
}

function psychosomatikPage() {
  { const _w = _needData("psychosomatik"); if (_w) return _w; }
  const entries = Object.entries(PSYCHOSOMATIK_KRANKHEITEN);
  const byKategorie = {};
  entries.forEach(([slug, k]) => {
    const kat = k.kategorie || "sonstige";
    (byKategorie[kat] = byKategorie[kat] || []).push([slug, k]);
  });
  const geplantByKategorie = PSYCHOSOMATIK_GEPLANT || {};
  const aktiveKategorien = PSYCHOSOMATIK_KATEGORIEN.filter(kat => byKategorie[kat.key] || (geplantByKategorie[kat.key] && geplantByKategorie[kat.key].length));

  const quickNav = aktiveKategorien.map(kat => {
    const f = kat.farbe || "var(--copper)";
    return `<a href="#" onclick="event.preventDefault();var el=document.getElementById('psy-${kat.key}');if(el)el.scrollIntoView({behavior:'smooth',block:'start'});"
      style="display:inline-block;padding:0.3rem 0.7rem;border-radius:6px;border:1.5px solid ${f};font-size:0.8rem;font-weight:700;color:${f};background:var(--bg);text-decoration:none;opacity:0.85;"
      onmouseover="this.style.opacity='1';this.style.background='color-mix(in srgb, ${f} 12%, var(--bg))'"
      onmouseout="this.style.opacity='0.85';this.style.background='var(--bg)'">${kat.label}</a>`;
  }).join("");

  const sections = aktiveKategorien.map(kat => {
    const f = kat.farbe || "var(--copper)";
    const items = (byKategorie[kat.key] || [])
      .slice()
      .sort((a, b) => a[1].titel.localeCompare(b[1].titel, "en"));
    const cards = items.map(([slug, k]) => `
      <button class="tool-card--link" data-route="psychosomatik/${slug}" style="display:block;width:100%;text-align:left;background:var(--ivory);border:1.5px solid var(--border);border-left:4px solid ${f};border-radius:12px;padding:1.1rem 1.3rem;margin-bottom:0.9rem;cursor:pointer;">
        <div style="display:flex;align-items:center;gap:0.7rem;margin-bottom:0.4rem;">
          <span style="font-size:1.4rem;">${k.icon}</span>
          <h3 style="margin:0;font-size:1.1rem;color:var(--ink);">${k.titel}</h3>
        </div>
        <p style="margin:0;font-size:0.9rem;color:var(--muted);">${k.kurz}</p>
      </button>
    `).join("");
    const geplant = (geplantByKategorie[kat.key] || []).slice().sort((a, b) => a.localeCompare(b, "en"));
    const geplantHtml = geplant.length ? `
      <div style="margin:${cards ? "0.3rem" : "0"} 0 0.9rem;">
        <p style="font-size:0.72rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.06em;margin:0 0 0.5rem;">In Preparation</p>
        <div style="display:flex;flex-wrap:wrap;gap:0.4rem;">
          ${geplant.map(titel => `<span style="display:inline-block;padding:0.3rem 0.65rem;border-radius:6px;background:color-mix(in srgb, ${f} 10%, var(--paper));color:color-mix(in srgb, ${f} 70%, var(--muted));font-size:0.82rem;">${titel}</span>`).join("")}
        </div>
      </div>
    ` : "";
    return `
      <div id="psy-${kat.key}" style="font-size:0.75rem;font-weight:700;letter-spacing:0.1em;color:${f};text-transform:uppercase;padding:1.2rem 0 0.4rem;margin-top:0.5rem;border-bottom:1.5px solid color-mix(in srgb, ${f} 30%, var(--paper));">${kat.label}</div>
      <div style="margin-top:0.8rem;">${cards}${geplantHtml}</div>
    `;
  }).join("");

  const subtypeRegister = [1,2,3,4,5,6,7,8,9].map(typNr => {
    const farbe = typeColor(typNr);
    return ["SE","SO","SX"].map(inst => {
      const code = inst + typNr;
      const tierKey = code.toLowerCase();
      return `<button data-route="psychosomatik-subtyp/${code}" style="display:inline-flex;align-items:center;gap:.35rem;padding:.35rem .7rem .35rem .4rem;border-radius:6px;border:1.5px solid ${farbe};background:var(--bg);color:${farbe};font-size:.82rem;font-weight:700;cursor:pointer;font-family:inherit;">
        <span style="position:relative;width:22px;height:22px;border-radius:50%;overflow:hidden;flex-shrink:0;display:inline-block;box-shadow:0 0 0 1.5px ${farbe};">
          <img src="https://pub-2851309644cc48aea2a2ae780b41b196.r2.dev/assets/tier-avatar-120/${tierKey}.jpg" alt="" loading="lazy" style="position:absolute;top:${tierAvatarTop(code)};left:${tierAvatarLeft(code)};width:140%;height:140%;object-fit:cover;" onerror="this.parentElement.style.display='none'" />
        </span>${code}</button>`;
    }).join("");
  }).join("");

  return shell(`
    <div class="page-container">
      ${pageHeader("psychosomatik")}
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:var(--ink);margin:1.2rem 0 0.5rem;">Psychosomatics Register</h1>
      <p class="psycho-intro">${entries.length} illnesses seen through a psychosomatic lens, connected to the Enneagram: where do typical inner patterns of a given subtype show up in connection with certain symptom pictures, among many other factors? <strong>Important: every person can develop any illness, regardless of subtype.</strong> This page does not replace a medical diagnosis or treatment, but offers a complementary, holistic layer of interpretation – in the same spirit as the Homeopathy section of this Compass: not addressing the symptom, but the underlying life force. The register is expanded with new conditions on a regular basis.</p>
      <img src="../assets/schaubilder/psychosomatik-register-header.jpg?v=2" alt="Body and Enneagram symbol as an image for the Psychosomatics Register" loading="lazy" style="width:100%;max-width:640px;border-radius:14px;margin:1.3rem 0;box-shadow:0 4px 18px rgba(0,0,0,.12);display:block;">
      <div style="background:var(--ivory);border:1px solid var(--border);border-radius:12px;padding:1.1rem 1.3rem;margin:0 0 1.3rem;max-width:640px;">
        <p style="font-size:0.75rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.07em;margin:0 0 0.4rem;">Search Register by Subtype</p>
        <p style="margin:0 0 0.8rem;font-size:0.88rem;color:var(--muted);">All conditions in this register filtered by subtype at a glance &ndash; e.g. how Heart Attack, and in time all other conditions, show up specifically for SE1 or SX7.</p>
        <div style="display:flex;flex-wrap:wrap;gap:0.4rem;">${subtypeRegister}</div>
      </div>
      <button class="tool-card--link" data-route="symptomlexikon" style="display:flex;align-items:center;gap:0.8rem;width:100%;text-align:left;background:var(--ivory);border:1.5px solid var(--border);border-radius:12px;padding:1rem 1.3rem;margin-bottom:1.3rem;max-width:640px;cursor:pointer;">
        <span style="font-size:1.5rem;">📖</span>
        <span>
          <span style="display:block;font-weight:700;color:var(--ink);font-size:1rem;">Symptom Lexicon</span>
          <span style="display:block;font-size:0.85rem;color:var(--muted);">Quick overview: which symptoms typically belong to which condition?</span>
        </span>
      </button>
      <div style="display:flex;flex-wrap:wrap;gap:0.5rem 0.4rem;margin:1.3rem 0 0.4rem;">
        ${quickNav}
      </div>
      <div style="max-width:640px;margin-top:0.6rem;">
        ${sections}
      </div>
      <img src="../assets/schaubilder/psychosomatik-register-beratung.jpg?v=2" alt="Consultation session with the Enneagram symbol and anatomical models on the table" loading="lazy" style="width:100%;max-width:640px;border-radius:14px;margin:1.6rem 0 1.3rem;box-shadow:0 4px 18px rgba(0,0,0,.12);display:block;">
      ${_psychosomatikBuecherHtml()}
      <section class="beratungs-cta" style="grid-template-columns:1fr;max-width:640px;">
        <div class="beratungs-cta__card beratungs-cta__card--behandlung">
          <div class="beratungs-cta__text">
            <p class="beratungs-cta__eyebrow">Naturheilpraxis Detlef Rathmer</p>
            <h3 class="beratungs-cta__title">Would you like your symptoms accompanied psychosomatically?</h3>
            <p class="beratungs-cta__body">Psychological Homeopathy connects the patterns of this register with an individual treatment tailored to your subtype. If you're interested in an initial consultation, feel free to reach out.</p>
          </div>
          <div class="beratungs-cta__contact">
            <a class="beratungs-cta__btn beratungs-cta__btn--secondary" href="mailto:detlefrathmer@t-online.de?subject=Inquiry%20about%20psychosomatic%20accompaniment">✉ Email</a>
            <a class="beratungs-cta__btn beratungs-cta__btn--whatsapp" href="https://wa.me/4915758786201?text=I%27d%20like%20to%20ask%20about%20psychosomatic%20accompaniment." target="_blank" rel="noopener">WhatsApp</a>
          </div>
          <a class="beratungs-cta__web" href="https://www.psychologische-homoeopathie.de" target="_blank" rel="noopener">Naturheilpraxis Detlef Rathmer → psychologische-homoeopathie.de</a>
        </div>
      </section>
      ${relatedLinks([
        {route:"healing", label:"Healing Compass"},
        {route:"homoeopathie", label:"Homeopathic Remedies"},
        {route:"tcm", label:"TCM & Meridians"},
      ])}
    </div>
  `);
}

function psychosomatikSubtypPage(code) {
  { const _w = _needData("psychosomatik"); if (_w) return _w; }
  code = (code || "").toUpperCase();
  const typNr = parseInt(code.slice(-1), 10);
  const farbe = typeColor(typNr);
  const entries = Object.entries(PSYCHOSOMATIK_KRANKHEITEN);
  const treffer = [];
  entries.forEach(([slug, k]) => {
    const t = (k.typen || []).find(t => t.typ === typNr);
    if (!t) return;
    const v = (t.varianten || []).find(v => v.code === code);
    if (!v) return;
    const kat = PSYCHOSOMATIK_KATEGORIEN.find(kt => kt.key === k.kategorie);
    treffer.push({ slug, k, v, kat });
  });

  const cards = treffer.length ? treffer.map(({ slug, k, v, kat }) => {
    const katFarbe = kat ? kat.farbe : farbe;
    return `
    <button class="tool-card--link" data-route="psychosomatik/${slug}" style="display:block;width:100%;text-align:left;background:var(--ivory);border:1.5px solid var(--border);border-left:4px solid ${katFarbe};border-radius:12px;padding:1.1rem 1.3rem;margin-bottom:0.9rem;cursor:pointer;">
      <div style="display:flex;align-items:center;gap:0.6rem;margin-bottom:0.5rem;">
        <span style="font-size:1.3rem;">${k.icon}</span>
        <div>
          <h3 style="margin:0;font-size:1.05rem;color:var(--ink);">${k.titel}</h3>
          ${kat ? `<p style="margin:0;font-size:0.72rem;color:${katFarbe};text-transform:uppercase;letter-spacing:0.05em;font-weight:700;">${kat.label}</p>` : ""}
        </div>
      </div>
      <p style="margin:0;font-size:0.9rem;line-height:1.6;color:var(--ink);">${v.text}</p>
    </button>
  `;
  }).join("") : `<p style="color:var(--muted);font-size:0.92rem;max-width:640px;">No conditions have been written up for ${code} yet &ndash; the register keeps growing, and new entries will appear here automatically as soon as they're added.</p>`;

  const subtypeNav = [1,2,3,4,5,6,7,8,9].map(t => {
    const f = typeColor(t);
    return ["SE","SO","SX"].map(inst => {
      const c = inst + t;
      const active = c === code;
      const tierKey = c.toLowerCase();
      return `<button data-route="psychosomatik-subtyp/${c}" style="display:inline-flex;align-items:center;gap:.3rem;padding:.3rem .6rem .3rem .35rem;border-radius:6px;border:1.5px solid ${f};background:${active ? f : "var(--bg)"};color:${active ? "#fff" : f};font-size:.78rem;font-weight:700;cursor:pointer;font-family:inherit;">
        <span style="position:relative;width:18px;height:18px;border-radius:50%;overflow:hidden;flex-shrink:0;display:inline-block;box-shadow:0 0 0 1.5px ${active ? "#fff" : f};">
          <img src="https://pub-2851309644cc48aea2a2ae780b41b196.r2.dev/assets/tier-avatar-120/${tierKey}.jpg" alt="" loading="lazy" style="position:absolute;top:${tierAvatarTop(c)};left:${tierAvatarLeft(c)};width:140%;height:140%;object-fit:cover;" onerror="this.parentElement.style.display='none'" />
        </span>${c}</button>`;
    }).join("");
  }).join("");

  return shell(`
    <div class="page-container">
      ${pageHeader("psychosomatik")}
      <button class="ghost-link" data-route="psychosomatik" style="margin-bottom:1rem;">&larr; All Conditions</button>
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:${farbe};margin:0 0 0.5rem;display:flex;align-items:center;gap:0.6rem;">
        <span style="position:relative;width:44px;height:44px;border-radius:50%;overflow:hidden;flex-shrink:0;display:inline-block;box-shadow:0 0 0 2px ${farbe};">
          <img src="https://pub-2851309644cc48aea2a2ae780b41b196.r2.dev/assets/tier-avatar-120/${code.toLowerCase()}.jpg" alt="" loading="lazy" style="position:absolute;top:${tierAvatarTop(code)};left:${tierAvatarLeft(code)};width:140%;height:140%;object-fit:cover;" onerror="this.parentElement.style.display='none'" />
        </span>${code}
      </h1>
      <p class="psycho-intro" style="max-width:640px;">All conditions from the Psychosomatics Register written up so far for the ${code} subtype &ndash; at a glance. <strong>Important: every person can develop any illness, regardless of subtype;</strong> this is about patterns that stand out in practice, not a statistical claim.</p>
      <div style="display:flex;flex-wrap:wrap;gap:0.35rem;margin:1.2rem 0 1.4rem;max-width:640px;">${subtypeNav}</div>
      <div style="max-width:640px;">${cards}</div>
      ${relatedLinks([
        {route:"psychosomatik", label:"All Conditions"},
        {route:"subtype/" + code.toLowerCase(), label:"Subtype Profile " + code},
      ])}
    </div>
  `);
}

function symptomlexikonPage() {
  { const _w = _needData("psychosomatik"); if (_w) return _w; }
  const entries = Object.entries(PSYCHOSOMATIK_KRANKHEITEN).filter(([, k]) => k.symptome && k.symptome.length);
  const byKategorie = {};
  entries.forEach(([slug, k]) => {
    const kat = k.kategorie || "sonstige";
    (byKategorie[kat] = byKategorie[kat] || []).push([slug, k]);
  });
  const geplantByKategorie = PSYCHOSOMATIK_GEPLANT || {};
  const aktiveKategorien = PSYCHOSOMATIK_KATEGORIEN.filter(kat => byKategorie[kat.key] || (geplantByKategorie[kat.key] && geplantByKategorie[kat.key].length));

  const quickNav = aktiveKategorien.map(kat => {
    const f = kat.farbe || "var(--copper)";
    return `<a href="#" onclick="event.preventDefault();var el=document.getElementById('sym-${kat.key}');if(el)el.scrollIntoView({behavior:'smooth',block:'start'});"
      style="display:inline-block;padding:0.3rem 0.7rem;border-radius:6px;border:1.5px solid ${f};font-size:0.8rem;font-weight:700;color:${f};background:var(--bg);text-decoration:none;opacity:0.85;"
      onmouseover="this.style.opacity='1';this.style.background='color-mix(in srgb, ${f} 12%, var(--bg))'"
      onmouseout="this.style.opacity='0.85';this.style.background='var(--bg)'">${kat.label}</a>`;
  }).join("");

  const sections = aktiveKategorien.map(kat => {
    const f = kat.farbe || "var(--copper)";
    const items = (byKategorie[kat.key] || []).slice().sort((a, b) => a[1].titel.localeCompare(b[1].titel, "en"));
    const cards = items.map(([slug, k]) => `
      <div style="background:var(--ivory);border:1.5px solid var(--border);border-left:4px solid ${f};border-radius:12px;padding:1.1rem 1.3rem;margin-bottom:0.9rem;">
        <div style="display:flex;align-items:center;gap:0.7rem;margin-bottom:0.5rem;">
          <span style="font-size:1.3rem;">${k.icon}</span>
          <h3 style="margin:0;font-size:1.05rem;color:var(--ink);">${k.titel}</h3>
        </div>
        <ul style="margin:0 0 0.7rem;padding-left:1.2rem;">
          ${k.symptome.map(s => `<li style="font-size:0.88rem;line-height:1.6;color:var(--ink);margin-bottom:0.25rem;">${s}</li>`).join("")}
        </ul>
        <button class="ghost-link" data-route="psychosomatik/${slug}" style="font-size:0.82rem;">More on ${k.titel} &rarr;</button>
      </div>
    `).join("");
    const geplant = (geplantByKategorie[kat.key] || []).slice().sort((a, b) => a.localeCompare(b, "en"));
    const geplantHtml = geplant.length ? `
      <div style="margin:${cards ? "0.3rem" : "0"} 0 0.9rem;">
        <p style="font-size:0.72rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.06em;margin:0 0 0.5rem;">In Preparation</p>
        <div style="display:flex;flex-wrap:wrap;gap:0.4rem;">
          ${geplant.map(titel => `<span style="display:inline-block;padding:0.3rem 0.65rem;border-radius:6px;background:color-mix(in srgb, ${f} 10%, var(--paper));color:color-mix(in srgb, ${f} 70%, var(--muted));font-size:0.82rem;">${titel}</span>`).join("")}
        </div>
      </div>
    ` : "";
    return `
      <div id="sym-${kat.key}" style="font-size:0.75rem;font-weight:700;letter-spacing:0.1em;color:${f};text-transform:uppercase;padding:1.2rem 0 0.4rem;margin-top:0.5rem;border-bottom:1.5px solid color-mix(in srgb, ${f} 30%, var(--paper));">${kat.label}</div>
      <div style="margin-top:0.8rem;">${cards}${geplantHtml}</div>
    `;
  }).join("");

  return shell(`
    <div class="page-container">
      ${pageHeader("symptomlexikon")}
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:var(--ink);margin:1.2rem 0 0.5rem;">Symptom Lexicon</h1>
      <p class="psycho-intro">A quick overview of typical symptoms for the conditions in the Psychosomatics Register – for a first orientation when the question comes up: &bdquo;Is this actually serious?&ldquo; <strong>Important: this lexicon does not replace a medical diagnosis.</strong> For acute, sudden, or severe symptoms, always seek medical or emergency care immediately instead of looking it up here. The full psychosomatic interpretation for each condition can be found in the <a href="javascript:void(0)" data-route="psychosomatik">Psychosomatics Register</a>.</p>
      <div style="display:flex;flex-wrap:wrap;gap:0.5rem 0.4rem;margin:1.3rem 0 0.4rem;">
        ${quickNav}
      </div>
      <div style="max-width:640px;margin-top:0.6rem;">
        ${sections}
      </div>
      ${relatedLinks([
        {route:"psychosomatik", label:"Psychosomatics Register"},
        {route:"healing", label:"Healing Compass"},
      ])}
    </div>
  `);
}

function psychosomatikDetailPage(slug) {
  { const _w = _needData("psychosomatik"); if (_w) return _w; }
  const k = PSYCHOSOMATIK_KRANKHEITEN[slug];
  if (!k) return psychosomatikPage();
  const subtypBloecke = k.typen.map(t => {
    const farbe = typeColor(t.typ);
    return `
    <div style="background:color-mix(in srgb, ${farbe} 5%, var(--paper));border-left:3px solid ${farbe};border-radius:0 8px 8px 0;padding:1.1rem 1.3rem;margin-bottom:1rem;max-width:640px;">
      <p style="font-size:0.78rem;font-weight:700;color:${farbe};text-transform:uppercase;letter-spacing:0.07em;margin:0 0 0.3rem;">Type ${t.typ}</p>
      <p style="font-family:var(--serif);font-size:1.1rem;color:var(--ink);margin:0 0 0.8rem;font-weight:600;">${t.titel}</p>
      ${t.varianten.map(v => `
        <p style="margin:0 0 0.7rem;font-size:0.93rem;line-height:1.65;color:var(--ink);">
          <span style="font-weight:700;color:${farbe};">${v.code}</span> &middot; ${v.text}
        </p>
      `).join("")}
    </div>
  `;
  }).join("");

  return shell(`
    <div class="page-container">
      ${pageHeader("psychosomatik")}
      <button class="ghost-link" data-route="psychosomatik" style="margin-bottom:1rem;">&larr; All Illnesses</button>
      <h1 style="font-family:'EB Garamond',serif;font-size:2rem;color:var(--ink);margin:0 0 0.6rem;">${k.icon} ${k.titel}</h1>
      ${k.definition ? `
      <div style="background:var(--ivory);border:1px solid var(--border);border-radius:10px;padding:1rem 1.2rem;margin-bottom:1rem;max-width:640px;">
        <p style="font-size:0.75rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.07em;margin:0 0 0.5rem;">Definition</p>
        <p style="margin:0;font-size:0.92rem;line-height:1.65;color:var(--ink);">${k.definition}</p>
      </div>` : ""}
      ${k.symptome && k.symptome.length ? `
      <div style="background:var(--ivory);border:1px solid var(--border);border-radius:10px;padding:1rem 1.2rem;margin-bottom:1rem;max-width:640px;">
        <p style="font-size:0.75rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.07em;margin:0 0 0.5rem;">Typical Symptoms</p>
        <ul style="margin:0;padding-left:1.2rem;">
          ${k.symptome.map(s => `<li style="font-size:0.92rem;line-height:1.65;color:var(--ink);margin-bottom:0.3rem;">${s}</li>`).join("")}
        </ul>
      </div>` : ""}
      ${k.notfall ? `
      <div style="background:color-mix(in srgb, #c0392b 10%, var(--paper));border:1.5px solid #c0392b;border-radius:10px;padding:1rem 1.2rem;margin-bottom:1rem;max-width:640px;">
        <p style="font-size:0.75rem;font-weight:700;color:#c0392b;text-transform:uppercase;letter-spacing:0.07em;margin:0 0 0.5rem;">⚠ Important Emergency Notice</p>
        <p style="margin:0;font-size:0.92rem;line-height:1.65;color:var(--ink);font-weight:600;">${k.notfall}</p>
      </div>` : ""}
      <div style="background:color-mix(in srgb, var(--copper) 8%, var(--paper));border-radius:10px;padding:1rem 1.2rem;margin-bottom:1.3rem;max-width:640px;">
        <p style="margin:0;font-size:0.88rem;font-style:italic;color:var(--muted);">${k.disclaimer}</p>
      </div>
      <p class="psycho-intro" style="max-width:640px;">${k.einleitung}</p>
      <p style="font-size:0.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:0.07em;margin:1.3rem 0 0.8rem;">Connections in the Enneagram</p>
      ${subtypBloecke}
      <p class="psycho-intro" style="max-width:640px;margin-top:1rem;">${k.abschluss}</p>
      ${relatedLinks([
        {route:"psychosomatik", label:"All Illnesses"},
        {route:"healing", label:"Healing Compass"},
        {route:"homoeopathie", label:"Homeopathic Remedies"},
      ])}
    </div>
  `);
}

function homoeopathiePage() {
  const param = state.route.split("/")[1];
  const typNr = param ? parseInt(param) : null;

  const DATA = [
    { typ:1, label:"Type 1 · The Order-Oriented", leidenschaft:"Anger", leidenschaftsMittel:"Platinum metallicum", wundeMittel:"Arsenicum album", thema:`Derived from the precious metal platinum – one of the purest, rarest and most resilient metals, untouched by any acid. This very signature shapes the remedy picture: a striving for purity, perfection and moral untouchability, combined with a subtle sense of elevation above the ordinary. Just as the metal cannot be tainted, the One wants to be flawless, correct and upright. The need to do everything right rests on a strong inner demand for perfection, order and integrity – and on the fear of diminishing oneself through error.`, wirkung:`Homeopathically it supports regulation where the life force manifests as strict control, inner pressure, tension and relentless self-condemnation. It helps loosen the high standards from their frozen rigidity, so that dignity and uprightness may remain without tipping into bitterness and superiority. The One may then rediscover measure and humanity – being right without judging oneself.` },
    { typ:2, label:"Type 2 · The Relationship-Oriented", leidenschaft:"Pride", leidenschaftsMittel:"Hyoscyamus niger", wundeMittel:"Pulsatilla pratensis", thema:`Derived from black henbane, a nightshade plant with a strongly intoxicating, disinhibiting effect. Its signature holds a desperate struggle for attention and love: jealousy, the need to be seen, and the fear of being abandoned or overlooked. This is precisely what shapes the Two’s remedy picture – the intense longing for closeness, recognition and being needed. The desire to be loved becomes so great that the person’s own centre slips from view.`, wirkung:`Homeopathically it supports regulation where the life force manifests as emotional dependency, possessiveness and fear of rejection. It helps calm the clinging appeal for affection and return love to a stable inner ground. Closeness may then arise without losing oneself or constantly fighting for validation.` },
    { typ:3, label:"Type 3 · The Success-Oriented", leidenschaft:"Deceit / Self-deception", leidenschaftsMittel:"Tarentula hispanica", wundeMittel:"Lycopodium clavatum", thema:`Derived from the Spanish tarantula – a restless creature whose bite, according to legend, compels feverish, driven dancing. This signature pervades the remedy picture: a relentless, hectic busyness, the need to impress, clever agility and a constant state of being under pressure. This is precisely what drives the Three – the strong impulse toward impact, success and recognition. Like the tarantula, the Three can barely pause, always in motion, always on stage.`, wirkung:`Homeopathically it supports regulation where the life force manifests as performance pressure, drivenness and mere functioning. It helps slow the inner tempo and uncouple worth from impact and applause. The Three may then find rest and sense that they are enough without constant brilliance.` },
    { typ:4, label:"Type 4 · The Identity-Seeker", leidenschaft:"Envy", leidenschaftsMittel:"Ignatia amara", wundeMittel:"Ignatia amara", thema:`Derived from the bean of the Ignatian tree – a seed with paradoxical, contradictory effects, long associated with grief and disappointed love. This signature shapes the remedy picture: fine sensitivity, shifting, contrasting moods, sighing and a tendency toward idealisation. This lives in the Four – the need to be true to oneself and to be understood, carried by deep longing for authenticity and meaning. Feeling swings between highs and lows, always in search of what is real.`, wirkung:`Homeopathically it supports regulation where emotional intensity, inner withdrawal and deep longing appear. It helps moderate the ups and downs of feeling without losing the depth. The Four may then rest in their sensitivity rather than losing themselves within it.` },
    { typ:5, label:"Type 5 · The Knowledge-Oriented", leidenschaft:"Avarice / Withdrawal", leidenschaftsMittel:"Stramonium", wundeMittel:"Silicea", thema:`The thorn apple is a highly toxic nightshade that evokes images of darkness, threat and terror. Its signature holds the need to protect oneself from an overwhelmingly experienced world and to seek inner ground. This shapes the Five’s remedy picture – the strong urge to withdraw in order to understand, carried by the search for knowledge, independence and inner clarity. Retreat into the mind becomes the safe place against an outer world that feels threatening.`, wirkung:`Homeopathically it supports regulation where mental withdrawal, inner isolation and overwhelm appear. It helps ease the distance from the world and make contact feel safer again. The Five may then step out of observation and participate in life without feeling threatened.` },
    { typ:6, label:"Type 6 · The Security-Oriented", leidenschaft:"Fear", leidenschaftsMittel:"Opium", wundeMittel:"Opium", thema:`Derived from the opium poppy – a substance that numbs pain, fear and perception and wraps everything in dull calm. This signature shows a being that longs for security and shelter and prefers to blank out danger rather than live through it. This shapes the passion of the Six – the strong wish for protection and the avoidance of threat. Where the remedy numbs, the soul seeks safety by dampening what unsettles.`, wirkung:`Homeopathically it supports regulation where excessive fear, inner tension, worry and permanent vigilance appear. It helps release the frozen shock-tension and calm the nervous system. In place of constant alertness, a sense of shelter may arise.` },
    { typ:7, label:"Type 7 · The Pleasure-Oriented", leidenschaft:"Gluttony", leidenschaftsMittel:"Belladonna", wundeMittel:"Calcium carbonicum", thema:`Deadly nightshade is a plant whose picture is shaped by heat, fever, fullness and glowing excitement. This signature pervades the remedy picture: feverish intensity, an urge toward vivid, strong impressions and a rapid flaring up. This lives in the Seven – the need to avoid pain and experience life to the full, carried by a feverish drive for more possibilities, stimulation and pleasure. Like the fever, everything wants to be bright, fast and intense.`, wirkung:`Homeopathically it supports regulation where the life force manifests as excess, restless drivenness and feverish stimulus-seeking. It helps cool and calm the overflowing excitement. The Seven may then enjoy abundance without being driven by it.` },
    { typ:8, label:"Type 8 · The Power-Oriented", leidenschaft:"Lust / Dominance", leidenschaftsMittel:"Veratrum album", wundeMittel:"Veratrum album", thema:`White hellebore is a powerful, toxic mountain plant whose picture is shaped by greatness, entitlement and sudden collapse. Its signature shows a mighty drive toward expansion, influence and superiority – reaching as far as harshness and arrogance. This is precisely what shapes the passion of the Eight – the need to be strong, independent and invulnerable, carried by a powerful inner drive for control. The force wants to expand and keep everything in hand.`, wirkung:`Homeopathically it supports regulation where the life force manifests as boundless expansion, excess and forcing of control. It helps moderate the overflowing force without losing the strength. The Eight may then lead and protect without overextending themselves and others.` },
    { typ:9, label:"Type 9 · The Harmony-Oriented", leidenschaft:"Sloth / Self-forgetting", leidenschaftsMittel:"Cannabis indica", wundeMittel:"Staphysagria", thema:`Indian hemp evokes images of fogging, dream-like distance and a blissful blurring of time and space. This signature shapes the remedy picture: a diving out of sharp reality into a soft, conflict-free numbness. This lives in the Nine – the need for peace and harmony, carried by the wish to avoid conflict, tension and upheaval. The world is softened so that nothing hurts or grates anymore.`, wirkung:`Homeopathically it supports regulation where the life force manifests as fogging, self-forgetting and diving out of one’s own presence. It helps become clearer and more wakefully present again. The Nine may then emerge from the fog and feel themselves once more.` },
  ];

  if (typNr && typNr >= 1 && typNr <= 9) {
    const d = DATA[typNr - 1];
    const sameMittel = d.leidenschaftsMittel === d.wundeMittel;
    return shell(`
      ${pageHeader("homoeopathie")}
      <div class="psycho-detail">
        <button class="ghost-link psycho-back" data-route="homoeopathie">&larr; All Types</button>
        <h1 class="psycho-detail__title">${d.label}</h1>
        <div class="remedy-detail-card" style="background:color-mix(in srgb, var(--copper) 6%, var(--paper));border:1px solid var(--line);border-radius:12px;padding:1.5rem;margin-bottom:1.5rem;max-width:640px;">
          <p style="font-size:.8rem;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin:0 0 .4rem;">Passion &middot; ${d.leidenschaft}</p>
          <div style="margin-bottom:1.2rem;">
            <span style="font-size:.75rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;">Passion Remedy</span>
            <p style="font-family:var(--serif);font-size:1.35rem;color:var(--copper);margin:.2rem 0 0;font-style:italic;">${d.leidenschaftsMittel}</p>
          </div>
          ${sameMittel ? "" : `
          <div style="padding-top:1rem;border-top:1px solid var(--line);">
            <span style="font-size:.75rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;">Wound Remedy</span>
            <p style="font-family:var(--serif);font-size:1.35rem;color:var(--copper);margin:.2rem 0 0;font-style:italic;">${d.wundeMittel}</p>
          </div>`}
          ${sameMittel ? `
          <p style="font-size:.8rem;color:var(--muted);margin:.6rem 0 0;padding-top:.8rem;border-top:1px solid var(--line);">Passion remedy and wound remedy are identical.</p>` : ""}
        </div>
        ${d.thema ? `
        <div style="background:color-mix(in srgb, var(--copper) 4%, var(--paper));border-left:3px solid var(--copper);border-radius:0 8px 8px 0;padding:1rem 1.2rem;margin-bottom:1rem;max-width:640px;">
          <p style="font-size:.78rem;font-weight:700;color:var(--copper);text-transform:uppercase;letter-spacing:.07em;margin:0 0 .5rem;">Remedy Portrait · ${d.leidenschaftsMittel}</p>
          <p style="font-size:.93rem;line-height:1.7;margin:0;color:var(--ink);">${d.thema}</p>
        </div>` : ""}
        ${d.wirkung ? `
        <div style="background:color-mix(in srgb, var(--copper) 4%, var(--paper));border-left:3px solid color-mix(in srgb, var(--copper) 60%, var(--paper));border-radius:0 8px 8px 0;padding:1rem 1.2rem;margin-bottom:1.5rem;max-width:640px;">
          <p style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin:0 0 .5rem;">Homeopathic Effect</p>
          <p style="font-size:.93rem;line-height:1.7;margin:0;color:var(--ink);">${d.wirkung}</p>
        </div>` : ""}
        ${AFFILIATE_LINKS.homoeopathie[d.leidenschaftsMittel] ? `<div style="max-width:640px;margin-bottom:1rem;">${affiliateBoxHtml("homoeopathie", d.leidenschaftsMittel)}</div>` : ""}
        ${(!sameMittel && AFFILIATE_LINKS.homoeopathie[d.wundeMittel]) ? `<div style="max-width:640px;margin-bottom:1rem;">${affiliateBoxHtml("homoeopathie", d.wundeMittel)}</div>` : ""}
        <p style="font-size:.8rem;color:var(--muted);font-style:italic;max-width:580px;">For use in therapeutic consultation only. The assignments apply to the core type – individual cases may call for additional remedies depending on wing, stress and integration direction.</p>
        <div style="margin-top:1.5rem;padding-top:1.2rem;border-top:1px solid var(--line);max-width:640px;">
          <p style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin:0 0 .6rem;">Subtype Detail · Remedies Compass</p>
          <div style="display:flex;gap:.6rem;flex-wrap:wrap;">
            <button class="ghost-link" data-route="subtype/se${typNr}" style="font-size:.85rem;padding:.35rem .75rem;border:1px solid var(--line);border-radius:6px;">SP${typNr} &ndash; Self-Preservation</button>
            <button class="ghost-link" data-route="subtype/so${typNr}" style="font-size:.85rem;padding:.35rem .75rem;border:1px solid var(--line);border-radius:6px;">SO${typNr} – Social</button>
            <button class="ghost-link" data-route="subtype/sx${typNr}" style="font-size:.85rem;padding:.35rem .75rem;border:1px solid var(--line);border-radius:6px;">SX${typNr} – Sexual</button>
          </div>
        </div>
        <div style="margin-top:1.5rem;padding-top:1.2rem;border-top:1px solid var(--line);max-width:640px;">
          <p style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;margin:0 0 .6rem;">Related Charts</p>
          <div style="display:flex;gap:.6rem;flex-wrap:wrap;">
            <button class="ghost-link" data-route="angst-essenz" style="font-size:.85rem;padding:.35rem .75rem;border:1px solid var(--line);border-radius:6px;">Fear → Essence</button>
          
            <button class="ghost-link" data-route="heilungsweg" style="font-size:.85rem;padding:.35rem .75rem;border:1px solid var(--line);border-radius:6px;">The Healing Path</button>
            <button class="ghost-link" data-route="laster-tugenden-affirmationen" style="font-size:.85rem;padding:.35rem .75rem;border:1px solid var(--line);border-radius:6px;">Vices · Virtues · Affirmations</button>
          </div>
        </div>
      </div>
    `);
  }

  // Overview
  return shell(`
    ${pageHeader("homoeopathie")}
    <section class="knowledge-hero">
      <div>
        <p class="eyebrow">Healing · Homeopathic Remedies</p>
        <h1>Homeopathic Remedies</h1>
        <p class="lead-small">Passion and wound remedies for all 9 Enneagram types – from homeopathic Enneagram practice according to the law of similars.</p>
      </div>
    </section>
    <section class="oils-grid" style="padding:0 1rem 3rem;">
      ${DATA.map(d => {
        const sameMittel = d.leidenschaftsMittel === d.wundeMittel;
        return `
        <article class="oil-card" style="cursor:pointer;" data-route="homoeopathie/${d.typ}">
          <div class="oil-card__body" style="padding:1.2rem;">
            <span class="oil-card__type">Type ${d.typ}</span>
            <h3 style="font-size:1rem;margin:.3rem 0 .6rem;">${d.label.split(" · ")[1]}</h3>
            <div style="margin-bottom:.5rem;">
              <span style="font-size:.7rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;display:block;margin-bottom:.15rem;">Passion Remedy</span>
              <span style="font-family:var(--serif);font-size:1.05rem;color:var(--copper);font-style:italic;">${d.leidenschaftsMittel}</span>
            </div>
            ${sameMittel ? "" : `
            <div style="margin-bottom:.5rem;padding-top:.5rem;border-top:1px solid var(--line);">
              <span style="font-size:.7rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;display:block;margin-bottom:.15rem;">Wound Remedy</span>
              <span style="font-family:var(--serif);font-size:1.05rem;color:var(--copper);font-style:italic;">${d.wundeMittel}</span>
            </div>`}
            <p style="font-size:.7rem;color:var(--muted);margin:.6rem 0 0;">Passion: ${d.leidenschaft}</p>
          </div>
        </article>`;
      }).join("")}
    </section>
    <p style="font-size:.8rem;color:var(--muted);font-style:italic;text-align:center;padding:0 1rem 2rem;max-width:580px;margin:0 auto;">For use in therapeutic consultation only. The assignments apply to the core type.</p>
  `);
}

