let YOGITEE = null;
_LAZY_DATA.yogitee = { spec: "../data/yogitee.js", assign: m => { YOGITEE = m.YOGITEE; } };
function yogiTeeKompassPage() {
  { const _w = _needData("yogitee"); if (_w) return _w; }
  const Y = YOGITEE.en;
  const nr = parseInt((state.route.split("/")[1] || "")) || 0;
  const tee = id => Y.tees.find(t => t.id === id);
  const az = q => "https://www.amazon.de/s?k=" + encodeURIComponent(q) + "&tag=enneagrammkom-21";
  const kauf = t => `<a href="${t.link || az(t.ean)}" target="_blank" rel="noopener sponsored" style="display:inline-block;font-size:.82rem;font-weight:600;color:var(--copper);border:1px solid var(--line);border-radius:6px;padding:.3rem .7rem;text-decoration:none;">View on Amazon (affiliate link)</a>`;
  const karte = (t, warum) => `<div style="border:1px solid var(--line);border-radius:12px;padding:.9rem 1rem;background:var(--paper);">
      <div style="font-weight:700;color:var(--ink);">${t.name}</div>
      <div style="font-size:.78rem;color:var(--muted);margin:.15rem 0 .5rem;">${Y.fam[t.fam]} &middot; ${t.zutaten.slice(0, 5).join(", ")}${t.kof ? " &middot; " + Y.ui.kof : ""}${t.lim ? " &middot; " + Y.ui.lim : ""}</div>
      ${warum ? `<p style="font-size:.9rem;line-height:1.6;margin:0 0 .6rem;">${warum}</p>` : ""}
      ${kauf(t)}
    </div>`;
  const grid = inner => `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:.8rem;margin:.8rem 0;">${inner}</div>`;
  const h2 = txt => `<h2 style="font-size:1.1rem;font-weight:700;margin:2rem 0 .6rem;color:var(--ink);">${txt}</h2>`;
  const hinweis = `<div style="margin:1.5rem 0 0;padding:1rem 1.2rem;background:color-mix(in srgb, var(--copper) 6%, var(--paper));border:1px solid var(--line);border-radius:10px;font-size:.84rem;line-height:1.65;color:var(--ink);">
      <p style="margin:0 0 .5rem;font-weight:700;color:var(--copper);text-transform:uppercase;letter-spacing:.04em;font-size:.78rem;">Important notes</p>
      <p style="margin:0 0 .5rem;">Enjoyment and ritual, not a health claim: this compass is a suggestion of which tea blend may suit your nature. It replaces neither medical or naturopathic advice nor treatment.</p><p style="margin:0 0 .5rem;">Licorice is in many varieties; with high blood pressure do not drink it in larger amounts. Black tea, green tea, white tea, maté and guarana contain caffeine. In pregnancy and breastfeeding, with medication or complaints, ask a doctor or pharmacist first; this applies especially to valerian, echinacea, sage and licorice.</p><p style="margin:0;">Yogi Tea® is a trademark of Yogi Tea GmbH. This is an independent recommendation with no connection to the brand. The links are affiliate links (Amazon Associates programme). Varieties and ingredients according to the manufacturer (yogi-life.com), as of October 2026: recipes and names may change, the packaging is binding. In other countries varieties have other names; for example Abendtee corresponds to the English Bedtime and Ingwer Orange Vanille to Ginger Orange.</p></div>`;
  let body = `<p style="margin:1.2rem 0 0;"><a href="${az("Yogi Tea Bio Tee")}" target="_blank" rel="noopener sponsored" style="display:inline-block;font-size:.9rem;font-weight:700;color:#fff;background:var(--copper);border-radius:8px;padding:.5rem 1rem;text-decoration:none;">View all Yogi Tea varieties on Amazon (affiliate link)</a></p>`;
  if (nr >= 1 && nr <= 9) {
    const T = Y.typen[nr];
    const instinkte = [["Self-preservation", "SE"], ["Social", "SO"], ["Sexual", "SX"]];
    body += `<button class="ghost-link" data-route="yogi-tee-kompass" style="margin:1.2rem 0 0;">&larr; All types</button>`;
    body += `<h2 style="font-size:1.25rem;font-weight:700;margin:1rem 0 .3rem;color:var(--ink);">Type ${nr} &ndash; ${T.anker}</h2><p class="vb-intro">${T.intro}</p>`;
    body += grid(T.tees.map(x => karte(tee(x.id), x.warum)).join(""));
    body += h2("The three subtypes of type " + nr);
    body += `<p style="font-size:.88rem;color:var(--muted);margin:0 0 .4rem;">The instinct comes on top of the type recommendation: the self-preservation subtype likes it warm, familiar and calm, the social one shared and convivial, the sexual one intense and spicy.</p>`;
    body += instinkte.map(([name, pre]) => {
      const code = "S" + (pre === "SE" ? "E" : pre.slice(1)) + nr;
      const disp = pre === "SE" ? "SP" + nr : code;
      const s = Y.sub[code];
      const tier = _TQ_TIERE[disp] || "";
      return `<div style="margin:1.2rem 0 0;"><h3 style="font-size:1rem;font-weight:700;margin:0 0 .3rem;color:var(--ink);">${disp} &middot; ${tier} <span style="font-weight:400;color:var(--muted);font-size:.85rem;">(${name})</span></h3><p style="font-size:.9rem;line-height:1.6;margin:0 0 .3rem;">${s.text}</p>${grid(s.tees.map(id => karte(tee(id))).join(""))}</div>`;
    }).join("");
  } else {
    body += h2("Choose your type");
    body += `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.8rem;">${[1,2,3,4,5,6,7,8,9].map(n => {
      const T = Y.typen[n];
      return `<button class="tool-card tool-card--link" data-route="yogi-tee-kompass/${n}"><span>Type ${n}</span><h2>${T.anker}</h2><p>${T.tees.map(x => tee(x.id).name).join(" &middot; ")}</p><span class="tool-card__arrow">View &rarr;</span></button>`;
    }).join("")}</div>`;
  }
  const alle = Y.tees.slice().sort((a, b) => a.name.localeCompare(b.name, "en"));
  body += `<details style="margin:2.2rem 0 0;"><summary style="cursor:pointer;font-weight:700;color:var(--ink);">All varieties at a glance (${alle.length})</summary><ul style="list-style:none;padding:0;margin:.8rem 0 0;font-size:.86rem;line-height:1.6;">${alle.map(t => `<li style="padding:.5rem 0;border-bottom:1px solid var(--line);"><strong>${t.name}</strong> <span style="color:var(--muted);">&middot; ${Y.fam[t.fam]}${t.kof ? " &middot; " + Y.ui.kof : ""}${t.lim ? " &middot; " + Y.ui.lim : ""}</span><br><span style="color:var(--muted);">${t.zutaten.join(", ")}</span><br>${kauf(t)}</li>`).join("")}</ul></details>`;
  return shell(`
    ${pageHeader("tee-enneagramm")}
    <section class="narrow">
      <p class="eyebrow">Knowledge &middot; Tea &amp; Enneagram</p>
      <h1>The Yogi Tea Compass</h1>
      ${nr ? "" : `<p class="lead-small">Yogi Tea comes in around 65 blends. Which one suits your Enneagram type, which your subtype? The compass leads from the type via the matching herb to concrete varieties.</p>
      <div class="psycho-img-wrap" style="margin-top:1.2rem;">
        <img src="${R2_CDN}assets/schaubilder/yogi-tee/yogi-tee-hero.jpg" alt="Steaming tea cup with saucer in backlight" class="psycho-img" loading="lazy" onerror="this.parentElement.style.display='none'" />
      </div>
      <div class="vb-section" style="max-width:100%;margin-top:1.4rem;">
        <p class="vb-intro">The assignment follows two steps. First the type: the Healing-Tea Compass gives each type one herb (lemon balm, rose, rosemary, willowherb, oat grass, chamomile, peppermint, ginger, fennel). Then Yogi blends are sought that contain this herb or match its mood.</p>
        <p class="vb-intro">Then comes the subtype: it shifts the choice toward its instinct, that is warm and familiar (self-preservation), shared and convivial (social) or intense and spicy (sexual). So each of the 27 subtypes gets two suggestions of its own.</p>
      </div>
        <div style="margin-top:1.2rem;padding:1.1rem 1.3rem;background:color-mix(in srgb, var(--copper) 7%, var(--paper));border:1px solid var(--line);border-left:4px solid var(--copper);border-radius:10px;font-size:.92rem;line-height:1.7;color:var(--ink);">
          <p style="margin:0 0 .6rem;font-weight:700;color:var(--copper);text-transform:uppercase;letter-spacing:.04em;font-size:.78rem;">A personal note from Detlef Rathmer</p>
          <p style="margin:0 0 .7rem;">I drink Yogi Tea myself, very happily, also as tea bags. I like the organic quality, in my view the ingredients are very well chosen, and the blends taste excellent. Even green tea, which many people do not like to drink, does not taste bitter in the blend ‘Grüne Energie’ (Green Energy): guarana, ginger, elderflower and natural flavourings make it fruity, aromatic and lively. I find it very easy to digest.</p><p style="margin:0 0 .7rem;">Then there is the tea bag tag at the end of the string. On each one is an affirmation, a short sentence you can take with you through the day. I like to use it as a prompt to pause briefly and gather myself.</p><p style="margin:0 0 .7rem;">Above all, though, the preparation itself is an exercise for me. Tea is a meditative drink. While pouring I like to think of the old Chinese saying that only an empty cup can be filled: if it is already full, nothing more goes in. Read spiritually, this is an invitation to make room inside. My tea time is a ritual, but not a fixed one; it is new every time: I turn to myself and to the energy field of my body and notice, for example, that I am tense again.</p><p style="margin:0;">That is why I consider it a very healing exercise to prepare oneself a tea two or three times a day, regardless of the effect of the tea itself. Which tea suits in the individual case has to be tried out. That is why there are several recommendations here each time: what matters is what really suits you.</p>
        </div>`}
      ${body}
      ${hinweis}
      ${relatedLinks([
        {route:"tee-enneagramm", label:"Tea &amp; Enneagram"},
        {route:"heiltees", label:"Healing Teas"},
        {route:"aetherische-oele", label:"Essential Oils"},
      ])}
    </section>
  `);
}


// Psychogramm-Seite: Lerncomic-Bild (typ-N-comic.jpg auf R2) mit Umschalter zur klassischen Fassung.
// Fehlt das Comic-Bild, bleibt die klassische Ansicht unverändert (kein Umschalter).
window._psychoComicReady = function (img) {
  const root = img.closest(".psycho-detail");
  if (!root) return;
  root.querySelector(".psycho-switch").style.display = "flex";
  window._psychoMode(root.querySelector('[data-psycho-mode="comic"]'), "comic");
};
window._psychoMode = function (btn, mode) {
  const root = btn.closest(".psycho-detail");
  if (!root) return;
  root.querySelector(".psycho-comic").style.display = mode === "comic" ? "block" : "none";
  root.querySelector(".psycho-classic").style.display = mode === "comic" ? "none" : "block";
  root.querySelectorAll(".psycho-switch button").forEach((b) => {
    const on = b === btn;
    b.setAttribute("aria-pressed", on ? "true" : "false");
    b.style.background = on ? "var(--copper,#a5652f)" : "transparent";
    b.style.color = on ? "#fff" : "var(--ink,#28241f)";
  });
};

function psychogrammePage() {
  const param = state.route.split("/")[1];
  const typNr = param ? parseInt(param) : null;

  if (typNr && typNr >= 1 && typNr <= 9) {
    const t = PSYCHOGRAMM_TYPEN[typNr - 1];
    return shell(`
      ${pageHeader("psychogramme")}
      <div class="psycho-detail">
        <button class="ghost-link psycho-back" data-route="psychogramme">← All Psychograms</button>
        <h1 class="psycho-detail__title">Type ${t.typ} &ndash; ${t.name}</h1>
        <p class="psycho-detail__kern">${t.kern}</p>
        <div class="psycho-switch" role="group" aria-label="Psychogram view" style="display:none;justify-content:center;gap:.5rem;margin:.2rem 0 1rem;">
          <button type="button" data-psycho-mode="comic" aria-pressed="false" onclick="window._psychoMode(this,'comic')" style="border:1px solid var(--copper,#a5652f);border-radius:999px;padding:.35rem 1rem;font:inherit;font-size:.9rem;cursor:pointer;">Learning comic</button>
          <button type="button" data-psycho-mode="classic" aria-pressed="false" onclick="window._psychoMode(this,'classic')" style="border:1px solid var(--copper,#a5652f);border-radius:999px;padding:.35rem 1rem;font:inherit;font-size:.9rem;cursor:pointer;">Classic</button>
        </div>
        <div class="psycho-img-wrap">
          <img src="/assets/schaubilder/psychogramme/typ-${t.typ}-comic-en.jpg" alt="Psychogram Type ${t.typ} (Learning comic)" class="psycho-img psycho-comic" style="display:none;" onload="window._psychoComicReady(this)" onerror="this.remove()" />
          <img src="${CDN}assets/schaubilder/psychogramme/typ-${t.typ}.jpg" alt="Psychogram Type ${t.typ}" class="psycho-img psycho-classic" />
        </div>
        ${psychogrammErklaerung(t.typ, "en")}
      </div>
    `);
  }

  // Overview of all 9 types
  return shell(`
    ${pageHeader("psychogramme")}
    <div class="psycho-wrap">
      <p class="eyebrow">Depth Psychology</p>
      <h1 class="section-title">Psychograms of the 9 Enneagram Types</h1>
      <p class="psycho-intro">Each psychogram shows the complete depth-psychological cycle of a type: from the Higher Self through the underlying feeling of deficiency to the fictitious self-image and shadow &mdash; and the path back to integration.</p>
      <details style="margin:1rem 0 1.4rem;padding:.9rem 1.1rem;border:1px solid var(--line,var(--border));border-left:4px solid var(--copper);border-radius:12px;background:var(--card,var(--paper));">
        <summary style="cursor:pointer;font-weight:700;color:var(--ink);">How to read a psychogram</summary>
        <div style="margin-top:.7rem;font-size:.92rem;line-height:1.6;color:var(--ink);">
          <p style="margin:0 0 .6rem;">A psychogram is read <strong>from top to bottom</strong>. It tells how an original quality becomes a protective pattern and how that pattern can dissolve again.</p>
          <ol style="margin:0 0 .6rem;padding-left:1.2rem;">
            <li><strong>Higher Self</strong> (top, blue): the original quality of the type, for example perfection for the One or love for the Nine.</li>
            <li><strong>Not being held / loss of contact with Being:</strong> the two experiences from which the pattern arises.</li>
            <li><strong>Underlying feeling of deficiency</strong> (purple) and the <strong>core sentence</strong> (red): the deep, mostly unconscious conviction about oneself, such as “Something is wrong with me”.</li>
            <li><strong>The five boxes:</strong> typical reactions with which the type answers this feeling.</li>
            <li><strong>The counter-strategy</strong> (green): the thought with which the type tries to compensate for the feeling of deficiency.</li>
            <li><strong>The speech bubble:</strong> the behaviour that only imitates the original quality (“an attempt to imitate …”).</li>
            <li><strong>Fictitious self-image</strong> (bottom left, light) and <strong>fictitious shadow</strong> (bottom right, dark): the image the type wants to show of itself, and what it does not want to see in itself. “Counter-type” means the variant that lives the opposite of what is expected.</li>
          </ol>
          <p style="margin:0;">The path to integration is in the lower boxes: recognise self-image and shadow and meet both with loving acceptance. More on wound, passion and healing path is in the subtype profiles.</p>
        </div>
      </details>
      <div class="psycho-grid">
        ${PSYCHOGRAMM_TYPEN.map(t => `
          <button class="psycho-card" data-route="psychogramme/${t.typ}" style="border-color:${typeColor(t.typ)};background:linear-gradient(160deg, ${typeColor(t.typ)}18, ${typeColor(t.typ)}08);">
            <span class="psycho-card__nr" style="color:${typeColor(t.typ)};">${t.typ}</span>
            <span class="psycho-card__name">${t.name}</span>
            <span class="psycho-card__kern">${t.kern}</span>
            <span class="psycho-card__arrow" style="color:${typeColor(t.typ)};">→</span>
          </button>
        `).join("")}
      </div>
      ${relatedLinks([
        {route:"ego-persoenlichkeit", label:"Ego Personality"},
        {route:"wer-wir-sind", label:"Who We Are"},
        {route:"aufmerksamkeitsfokus", label:"Focus of Attention"},
      ])}
    </div>
  `);
}

// ── Typalbum: IndexedDB-Helfer ──────────────────────────────────────────────
const ALBUM_DB = "kompass-typalbum";
const ALBUM_STORE = "fotos";

function albumDb() {
  return new Promise((res, rej) => {
    const req = indexedDB.open(ALBUM_DB, 1);
    req.onupgradeneeded = e => e.target.result.createObjectStore(ALBUM_STORE);
    req.onsuccess = e => res(e.target.result);
    req.onerror   = e => rej(e.target.error);
  });
}
async function albumGet(code) {
  const db = await albumDb();
  return new Promise((res, rej) => {
    const tx = db.transaction(ALBUM_STORE, "readonly");
    const req = tx.objectStore(ALBUM_STORE).get(code);
    req.onsuccess = () => res(req.result || []);
    req.onerror   = () => rej(req.error);
  });
}
async function albumSet(code, arr) {
  const db = await albumDb();
  return new Promise((res, rej) => {
    const tx = db.transaction(ALBUM_STORE, "readwrite");
    const req = tx.objectStore(ALBUM_STORE).put(arr, code);
    req.onsuccess = () => res();
    req.onerror   = () => rej(req.error);
  });
}

